        D1620.solve_case(n, ar, t - 1)

    @staticmethod
    def solve_case(n, ar, remaining_cases):
        ans = float('inf')
        for j in range(3):
            for k in range(3):
                mod3 = [[0, float('inf')] for _ in range(10)]
                mod3[0][0] = 1
                mod3[0][1] = 0
                for l in range(j + 1):
                    for m in range(k + 1):
                        sum_val = l + m * 2
                        if sum_val < 10:
                            mod3[sum_val][0] = 1
                            mod3[sum_val][1] = min(l + m, mod3[sum_val][1])
                mx = 0
                for l in range(n):
                    mod = ar[l] % 3
                    mn = float('inf')
                    for m in range(mod, ar[l] + 1, 3):  # Corrected the range to avoid out of range error
                        if mod3[m][0] == 1:
                            mn = min((ar[l] - m) // 3, mn)
                    mx = max(mx, mn)
                if mx != float('inf'):
                    ans = min(ans, mx + j + k)
        print(ans)
