type C_BA_String struct{}

func (c *C_BA_String) solve(n, k, x int, s string) {
	var res []rune
	x--
	for i := n - 1; i >= 0; i-- {
		if s[i] == 'a' {
			res = append(res, 'a')
		} else {
			count := 1
			for i-count >= 0 && s[i] == s[i-count] {
				count++
			}
			base := count*k + 1
			for j := 0; j < x%base; j++ {
				res = append(res, 'b')
			}
			x /= base
			i -= count - 1
		}
	}

	for i, j := 0, len(res)-1; i < j; i, j = i+1, j-1 {
		res[i], res[j] = res[j], res[i]
	}

	fmt.Println(string(res))
}

func (c *C_BA_String) main() {
	scanner := bufio.NewScanner(os.Stdin)
	var input []string
	for scanner.Scan() {
		input = append(input, scanner.Text())
	}

	t, _ := strconv.Atoi(input[0])
	index := 1

	for i := 0; i < t; i++ {
		parts := strings.Split(input[index], " ")
		n, _ := strconv.Atoi(parts[0])
		k, _ := strconv.Atoi(parts[1])
		x, _ := strconv.Atoi(parts[2])
		s := input[index+1]
		index += 2
		c.solve(n, k, x, s)
	}
}

