func (d *D1620) Main() {
	reader := bufio.NewReader(os.Stdin)
	t, _ := strconv.Atoi(readLine(reader))
	d.processCases(t, reader)
}

func (d *D1620) processCases(t int, reader *bufio.Reader) {
	if t == 0 {
		return
	}
	n, _ := strconv.Atoi(readLine(reader))
	ar := readIntArray(reader, n)
	d.solveCase(n, ar, reader, t-1)
}

func (d *D1620) solveCase(n int, ar []int, reader *bufio.Reader, remainingCases int) {
	ans := 1<<63 - 1
	for j := 0; j < 3; j++ {
		for k := 0; k < 3; k++ {
			mod3 := make([][2]int, 10)
			for i := range mod3 {
				mod3[i] = [2]int{0, 1<<63 - 1}
			}
			mod3[0][0] = 1
			mod3[0][1] = 0
			for l := 0; l <= j; l++ {
				for m := 0; m <= k; m++ {
					sum := l + m*2
					if sum < 10 {
						mod3[sum][0] = 1
						mod3[sum][1] = min(l+m, mod3[sum][1])
					}
				}
			}
			mx := 0
			for l := 0; l < n; l++ {
				mod := ar[l] % 3
				mn := 1<<63 - 1
				for m := mod; m <= ar[l] && m <= 9; m += 3 {
					if mod3[m][0] == 1 {
						mn = min((ar[l]-m)/3, mn)
					}
				}
				mx = max(mx, mn)
			}
			if mx != 1<<63-1 {
				ans = min(ans, mx+j+k)
			}
		}
	}
	fmt.Println(ans)
	if remainingCases > 0 {
		d.processCases(remainingCases, reader)
	} else {
		reader.ReadString('\n')
	}
}

