}

func readIntArray(reader *bufio.Reader, n int) []int {
	input := strings.Fields(readLine(reader))
	ar := make([]int, n)
	for i := 0; i < n; i++ {
		ar[i], _ = strconv.Atoi(input[i])
	}
	return ar
}

