func main() {
	var n int
	var p [][2]int
	var r [][]int
	var q []int
	var ans, cnt int

	scanner := bufio.NewScanner(os.Stdin)
	if scanner.Scan() {
		n, _ = strconv.Atoi(scanner.Text())
		p = make([][2]int, 0, n)
		r = make([][]int, n)
		q = make([]int, n)
		for i := range r {
			r[i] = make([]int, n)
		}
	}

	for scanner.Scan() {
		line := strings.Fields(scanner.Text())
		x, _ := strconv.Atoi(line[0])
