public class Main {
    public static void solve(int n, int k, int x, String s) {
        List<Character> res = new ArrayList<>();
        x--;
        for (int i = n - 1; i >= 0; i--) {
            if (s.charAt(i) == 'a') {
                res.add('a');
            } else {
                int count = 1;
                while (i - count >= 0 && s.charAt(i) == s.charAt(i - count)) {
                    count++;
                }
                final int base = count * k + 1;
                for (int j = 0; j < x % base; j++) {
                    res.add('b');
                }
                x /= base;
                i = i - count + 1;
            }
        }
        StringBuilder result = new StringBuilder();
        for (int i = res.size() - 1; i >= 0; i--) {
            result.append(res.get(i));
        }
        System.out.println(result.toString());
