public class Main {
    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int t = Integer.parseInt(br.readLine());
        processCases(t, br);
    }

    private static void processCases(int t, BufferedReader br) throws Exception {
        if (t == 0) return;
        int n = Integer.parseInt(br.readLine());
        String[] input = br.readLine().split(" ");
        int[] ar = Arrays.stream(input).mapToInt(Integer::parseInt).toArray();
        solveCase(n, ar, br, t - 1);
    }

    private static void solveCase(int n, int[] ar, BufferedReader br, int remainingCases) throws Exception {
        int ans = Integer.MAX_VALUE;
        for (int j = 0; j < 3; j++) {
            for (int k = 0; k < 3; k++) {
                int[][] mod3 = new int[10][2];
                for (int[] row : mod3) {
                    Arrays.fill(row, -1);
                }
                mod3[0][0] = 1;
                mod3[0][1] = 0;
                for (int l = 0; l <= j; l++) {
                    for (int m = 0; m <= k; m++) {
                        int sum = l + m * 2;
                        if (sum < 10) {
                            mod3[sum][0] = 1;
                            mod3[sum][1] = Math.min(l + m, mod3[sum][1]);
                        }
                    }
                }
                int mx = 0;
                for (int l = 0; l < n; l++) {
                    int mod = ar[l] % 3;
                    int mn = Integer.MAX_VALUE;
                    for (int m = mod; m <= ar[l] && m <= 9; m += 3) {
                        if (mod3[m][0] == 1) {
                            mn = Math.min((ar[l] - m) / 3, mn);
                        }
                    }
                    mx = Math.max(mx, mn);
                }
                if (mx != Integer.MAX_VALUE) {
                    ans = Math.min(ans, mx + j + k);
                }
            }
        }
        System.out.println(ans);
        if (remainingCases > 0) {
            processCases(remainingCases, br);
        } else {
            br.close();
        }
    }
}

