public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());
        List<int[]> p = new ArrayList<>();
        int[][] r = new int[n][n];
        int[] q = new int[n];
        int ans = 0;
        int cnt = 0;

        while (p.size() < n) {
            String[] line = scanner.nextLine().split(" ");
            int x = Integer.parseInt(line[0]);
            int y = Integer.parseInt(line[1]);
            p.add(new int[]{x, y});

            if (p.size() == n) {
                for (int i = 0; i < n; i++) {
                    for (int j = i + 1; j < n; j++) {
                        int gcd = gcd(Math.abs(p.get(i)[0] - p.get(j)[0]), Math.abs(p.get(i)[1] - p.get(j)[1]));
                        if (gcd % 4 == 0) {
                            cnt++;
                            r[i][j] = 1;
                            q[i]++;
                            ans += n - 2;
                        }
                    }
                }
                for (int i = 0; i < n; i++) {
                    for (int j = 1; j < n; j++) {
                        if (r[i][j] == 1) {
                            ans -= q[j] * 2;
                        }
                    }
                }
                System.out.println(ans);
            }
        }
    }

    private static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

