struct D1620;

impl D1620 {
    fn main() {
        let mut input = String::new();
        io::stdin().read_line(&mut input).unwrap();
        let t: i32 = input.trim().parse().unwrap();
        Self::process_cases(t);
    }

    fn process_cases(mut t: i32) {
        if t == 0 {
            return;
        }
        let mut input = String::new();
        io::stdin().read_line(&mut input).unwrap();
        let n: usize = input.trim().parse().unwrap();
        let mut ar = vec![0; n];
        io::stdin().read_line(&mut input).unwrap();
        for (i, num) in input.trim().split_whitespace().enumerate() {
            ar[i] = num.parse().unwrap();
        }
        Self::solve_case(n, &ar);
        t -= 1;
        if t > 0 {
            Self::process_cases(t);
        }
    }

    fn solve_case(n: usize, ar: &[i32]) {
        let mut ans = i32::MAX;
        for j in 0..3 {
            for k in 0..3 {
                let mut mod3 = vec![vec![0, i32::MAX]; 10];
                mod3[0][0] = 1;
                mod3[0][1] = 0;
                for l in 0..=j {
                    for m in 0..=k {
                        let sum = l + m * 2;
                        if sum < 10 {
                            mod3[sum][0] = 1;
                            mod3[sum][1] = mod3[sum][1].min(l as i32 + m);
                        }
                    }
                }
                let mut mx = 0;
                for &num in ar.iter().take(n) {
                    let mod_val = num % 3;
                    let mut mn = i32::MAX;
                    for m in (mod_val..=num).step_by(3).take_while(|&x| x <= 9) {
                        if mod3[m as usize][0] == 1 {
                            mn = mn.min((num - m) / 3);
                        }
                    }
                    mx = mx.max(mn);
                }
                if mx != i32::MAX {
                    ans = ans.min(mx + j as i32 + k);
                }
            }
        }
        println!("{}", ans);
    }
}

