private:
    static void processCases(int t) {
        if (t == 0) return;
        int n;
        std::cin >> n;
        std::vector<int> ar(n);
        for (int i = 0; i < n; ++i) {
            std::cin >> ar[i];
        }
        solveCase(n, ar, t - 1);
    }

    static void solveCase(int n, const std::vector<int>& ar, int remainingCases) {
        int ans = std::numeric_limits<int>::max();
        for (int j = 0; j < 3; ++j) {
            for (int k = 0; k < 3; ++k) {
                std::vector<std::pair<int, int>> mod3(10, {0, std::numeric_limits<int>::max()});
                mod3[0] = {1, 0};
                for (int l = 0; l <= j; ++l) {
                    for (int m = 0; m <= k; ++m) {
                        int sum = l + m * 2;
                        if (sum < 10) {
                            mod3[sum] = {1, std::min(l + m, mod3[sum].second)};
                        }
                    }
                }
                int mx = 0;
                for (int l = 0; l < n; ++l) {
                    int mod = ar[l] % 3;
                    int mn = std::numeric_limits<int>::max();
                    for (int m = mod; m <= ar[l] && m <= 9; m += 3) {
                        if (mod3[m].first == 1) {
                            mn = std::min((ar[l] - m) / 3, mn);
                        }
                    }
                    mx = std::max(mx, mn);
                }
                if (mx != std::numeric_limits<int>::max()) {
                    ans = std::min(ans, mx + j + k);
                }
            }
        }
        std::cout << ans << std::endl;
        if (remainingCases > 0) {
            processCases(remainingCases);
        }
    }
};

