    }
    t--;
    rl.question('', (input) => {
        const n: number = parseInt(input.trim());
        const dp1: number[] = new Array(n + 2).fill(0);
        const dp2: number[] = new Array(n + 2).fill(0);
        dp1[0] = 1;

        rl.question('', (input) => {
            processNumbers(input, n, dp1, dp2);
            calculateAndPrintAnswer(dp1, dp2);
            readNextLine(t, rl);
        });
    });
}

function processNumbers(input: string, n: number, dp1: number[], dp2: number[]) {
    const nums: number[] = input.trim().split(' ').map(Number);
    for (const num of nums) {
        dp1[num + 1] = ((dp1[num + 1] << 1) % mod + dp1[num]) % mod;
        if (num > 0) {
            dp2[num - 1] = ((dp2[num - 1] << 1) % mod + dp1[num - 1]) % mod;
        }
        dp2[num + 1] = ((dp2[num + 1] << 1) % mod) % mod;
    }
}

