class FastIO {
    private reader: NodeJS.ReadStream;
    private writer: NodeJS.WriteStream;
    private buffer: string = '';

    constructor(file: NodeJS.ReadStream, outFile: NodeJS.WriteStream) {
        this.reader = file;
        this.writer = outFile;
        this.initReader();
    }

    private async initReader(): Promise<void> {
        for await (const chunk of this.reader) {
            this.buffer += chunk.toString();
        }
    }

    read(): string {
        let buffer = '';
        while (true) {
            const index = this.buffer.indexOf('\n');
            if (index === -1) break;
            buffer += this.buffer.substring(0, index + 1);
            this.buffer = this.buffer.substring(index + 1);
        }
        return buffer;
    }

    readLine(): string {
        const index = this.buffer.indexOf('\n');
        if (index === -1) return '';
        const line = this.buffer.substring(0, index);
        this.buffer = this.buffer.substring(index + 1);
        return line;
    }

    write(s: string): void {
        this.writer.write(s);
    }

    flush(): void {
        this.writer.flush();
    }
}

