const MOD = 998244353;

function egcd(a: number, b: number): [number, number, number] {
    if (a === 0) {
        return [b, 0, 1];
    }
    const [g, y, x] = egcd(b % a, a);
    return [g, x - Math.floor(b / a) * y, y];
}

function modinv(a: number, m: number): number {
    const [g, x] = egcd(a, m);
    if (g !== 1) {
        throw new Error("modular inverse does not exist");
    }
    return ((x % m) + m) % m;
}

function choose(n: number, k: number, p: number): number {
    if (k === 0 || n < k) {
        return 1;
    }
    let x = 1;
    for (let i = 0; i < k; i++) {
        x = (x * (n - i)) % p;
        const d = i + 1;
        x = (x * modinv(d, p)) % p;
    }
    return x;
}

function solve() {
    process.stdin.on('data', (chunk: Buffer) => {
        const input = chunk.toString().trim().split('\n');
        const n = parseInt(input[0].trim(), 10);
        const lines = input.slice(1);

        let wb_poss = true;
        let bw_poss = true;
        let w = 0;
        let b = 0;
        let q = 0;
        let free = 0;
        let any_bad_poss = true;

        for (const s of lines) {
            if (s[0] === 'B') {
                b++;
                wb_poss = false;
            } else if (s[0] === 'W') {
                w++;
                bw_poss = false;
            } else if (s[0] === '?') {
                q++;
            }
            if (s[1] === 'B') {
                b++;
                bw_poss = false;
            } else if (s[1] === 'W') {
                w++;
                wb_poss = false;
            } else if (s[1] === '?') {
                q++;
            }
            if (s === "??") {
                free++;
            } else if (s[0] === s[1]) {
                any_bad_poss = false;
            }
        }

        const w_needed = n - w;
        if (w_needed > q || w_needed < 0) {
            process.stdout.write("0\n");
            return;
        }

        let num_bad_poss: number;
        if (any_bad_poss) {
            num_bad_poss = pow(2, free, MOD);
            if (wb_poss) {
                num_bad_poss--;
            }
            if (bw_poss) {
                num_bad_poss--;
            }
        } else {
            num_bad_poss = 0;
        }

        process.stdout.write(((choose(q, w_needed, MOD) - num_bad_poss + MOD) % MOD).toString() + "\n");
    });
}

function pow(base: number, exp: number, mod: number): number {
    let result = 1;
    while (exp > 0) {
        if (exp % 2 === 1) {
            result = (result * base) % mod;
        }
        exp >>= 1;
        base = (base * base) % mod;
    }
    return result;
}

