const BUFSIZE = 8192;

class FastIO {
    private fd: NodeJS.ReadableStream;
    private buffer: string;
    private writable: boolean;

    constructor(file: NodeJS.ReadableStream) {
        this.fd = file;
        this.buffer = '';
        this.writable = file !== process.stdin;
    }

    async read(): Promise<string> {
        let b = '';
        for (;;) {
            const buf = Buffer.alloc(BUFSIZE);
            const n = await new Promise<number>((resolve, reject) => {
                this.fd.read(buf, 0, BUFSIZE, null, (err, bytesRead) => {
                    if (err) reject(err);
                    else resolve(bytesRead || 0);
                });
            });
            if (n === 0) break;
            b += buf.toString('utf-8', 0, n);
        }
        return b;
    }

    async readLine(): Promise<string> {
        let b = '';
        for (;;) {
            const buf = Buffer.alloc(BUFSIZE);
            const n = await new Promise<number>((resolve, reject) => {
                this.fd.read(buf, 0, BUFSIZE, null, (err, bytesRead) => {
                    if (err) reject(err);
                    else resolve(bytesRead || 0);
                });
            });
            if (n === 0) break;
            b += buf.toString('utf-8', 0, n);
            if (b.includes('\n')) break;
        }
        return b.trimEnd();
    }

    flush(): void {
        if (this.writable) {
            process.stdout.write(this.buffer);
            this.buffer = '';
        }
    }
}

class IOWrapper {
    private buffer: NodeJS.ReadableStream;
    private writable: boolean;

    constructor(file: NodeJS.ReadableStream) {
        this.buffer = file;
        this.writable = file !== process.stdin;
    }

    async read(): Promise<string> {
        const b = await new Promise<string>((resolve, reject) => {
            let data = '';
            this.buffer.on('data', chunk => data += chunk.toString());
            this.buffer.on('end', () => resolve(data));
            this.buffer.on('error', reject);
        });
        return b.trimEnd();
    }

    async readLine(): Promise<string> {
        const b = await new Promise<string>((resolve, reject) => {
            let data = '';
            this.buffer.on('data', chunk => data += chunk.toString());
            this.buffer.on('end', () => resolve(data));
            this.buffer.on('error', reject);
        });
        return b.trimEnd();
    }

    flush(): void {
        if (this.writable) {
            process.stdout.flush();
        }
    }
}

