class Scanner {
    private reader: readline.Interface;
    private buffer: string[] = [];

    constructor(reader: readline.Interface) {
        this.reader = reader;
        this.reader.on('line', (line) => {
            this.buffer.push(...line.trim().split(/\s+/));
        });
    }

    public next(): string {
        if (this.buffer.length === 0) {
            throw new Error("No more input");
        }
        return this.buffer.shift()!;
    }

    public nextInt(): number {
        return parseInt(this.next(), 10);
    }

    public nextLong(): number {
        return parseInt(this.next(), 10);
    }

    public nextDouble(): number {
        return parseFloat(this.next());
    }

    public readArray(n: number): number[] {
        const a: number[] = [];
        for (let i = 0; i < n; i++) {
            a.push(this.nextInt());
        }
        return a;
    }

    public nextLine(): string {
        if (this.buffer.length === 0) {
            throw new Error("No more input");
        }
        const line = this.buffer.join(' ');
        this.buffer = [];
        return line;
    }
}

