                dp1[num + 1] = (dp1[num + 1] * 2) % MOD;
                dp1[num + 1] = (dp1[num + 1] + dp1[num]) % MOD;
                if (num > 0) {
                    dp2[num - 1] = (dp2[num - 1] * 2) % MOD;
                    dp2[num - 1] = (dp2[num - 1] + dp1[num - 1]) % MOD;
                }
                dp2[num + 1] = (dp2[num + 1] * 2) % MOD;
            }

            int ans = 0;
            for (int j = 0; j < n + 2; j++) {
                ans = (ans + dp1[j] + dp2[j]) % MOD;
            }
            if (ans > 0) {
                writer.write(String.valueOf(ans - 1));
            } else {
                writer.write(String.valueOf(MOD - 1));
            }
            writer.newLine();
        }

        writer.flush();
        reader.close();
        writer.close();
    }
}

import java.io.*;
import java.util.*;

public class Main {
    public static int[] nextLargerElement(int[] arr, int n, boolean f) {
        Stack<Integer> s = new Stack<>();
        int[] ans = new int[n];
        Arrays.fill(ans, -1);
        for (int i = 0; i < n; i++) {
            while (!s.isEmpty() && arr[s.peek()] < arr[i]) {
                s.pop();
            }
            if (!s.isEmpty()) {
                ans[i] = s.peek();
            }
            s.push(i);
        }
        if (f) {
            for (int i = 0; i < n; i++) {
                if (ans[i] != -1) {
                    ans[i] = n - 1 - ans[i];
                }
            }
        }
        return ans;
    }

    public static int dfs(int i, List<List<Integer>> adj, int p, int ans) {
        boolean f = true;
        int a1 = 0;
        for (int j : adj.get(i)) {
            if (j != p) {
                a1 += dfs(j, adj, i, ans + 1);
                f = false;
            }
        }
        if (f) {
            a1 += ans * (ans - 1) / 2;
        }
        return a1;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        BufferedWriter writer = new BufferedWriter(new OutputStreamWriter(System.out));

        int t = Integer.parseInt(reader.readLine());

        for (int i = 0; i < t; i++) {
            String[] parts = reader.readLine().split(" ");
            int n = Integer.parseInt(parts[0]);
            int s = Integer.parseInt(parts[1]);
            writer.write(s / ((n + 2) / 2) + "\n");
        }

        writer.flush();
        reader.close();
        writer.close();
    }
}

