    static long pos;
    static ArrayList<Long> ans = new ArrayList<>();

    public static void goFunc() {
        ans.add(pos);
        for (long i = 1; i <= pos / 2; i++) {
            long temp = a[(int)i];
            a[(int)i] = a[(int)(pos - i + 1)];
            a[(int)(pos - i + 1)] = temp;
        }
    }

    public static void solve() {
        Scanner scanner = new Scanner(System.in);
        long n = scanner.nextLong();
        for (long i = 1; i <= n; i++) {
            if (scanner.hasNextLong()) {
                a[(int)i] = scanner.nextLong();
            } else {
                System.out.println("-1");
                return;
            }
        }
        ans.clear();
        for (long i = 1; i <= n; i++) {
            if (i % 2 != a[(int)i] % 2) {
                System.out.println("-1");
                return;
            }
        }
        for (long i = n; i > 1; i -= 2) {
            boolean found = false;
            for (long j = 1; j <= n; j++) {
                if (a[(int)j] == i) {
                    pos = j;
                    found = true;
                    break;
                }
            }
            if (!found) {
                System.out.println("-1");
                return;
            }
            goFunc();
            found = false;
            for (long j = 1; j <= n; j++) {
                if (a[(int)j] == i - 1) {
                    pos = j - 1;
                    found = true;
                    break;
                }
            }
            if (!found) {
                System.out.println("-1");
                return;
            }
            goFunc();
            found = false;
            for (long j = 1; j <= n; j++) {
                if (a[(int)j] == i - 1) {
                    pos = j + 1;
                    found = true;
                    break;
                }
            }
            if (!found) {
                System.out.println("-1");
                return;
            }
            goFunc();
            pos = 3;
            goFunc();
            pos = i;
            goFunc();
        }
        System.out.println(ans.size());
        for (long v : ans) {
            System.out.print(v + " ");
        }
        System.out.println();
    }

