            mocha.add(new ArrayList<>());
            cMocha[i] = i;
            cDiana[i] = i;
        }

        for (int i = 0; i < m1; i++) {
            input = reader.readLine();
            parts = input.split("\\s+");
            int u = Integer.parseInt(parts[0]);
            int v = Integer.parseInt(parts[1]);
            mocha.get(u).add(v);
