            int v = Integer.parseInt(parts[1]);
            diana.get(u).add(v);
            diana.get(v).add(u);
        }

        int compsM = marker1(n);
        int compsD = marker2(n);

        int min = Math.min(compsD, compsM);

        int ans = 0;

        boolean[] connD = new boolean[n + 1];
