import java.util.Scanner;

public class Main {

    private static final int MOD = 998244353;

    public static void main(String[] args) {
        solve();
    }

    private static void solve() {
        Scanner scanner = new Scanner(System.in);
        int n = scanner.nextInt();

        boolean wb_poss = true;
        boolean bw_poss = true;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        boolean any_bad_poss = true;

        for (int i = 0; i < n; i++) {
            String s = scanner.next();
            if (s.charAt(0) == 'B') {
                b++;
                wb_poss = false;
            } else if (s.charAt(0) == 'W') {
                w++;
                bw_poss = false;
            } else if (s.charAt(0) == '?') {
                q++;
            }
            if (s.charAt(1) == 'B') {
                b++;
                bw_poss = false;
            } else if (s.charAt(1) == 'W') {
                w++;
                wb_poss = false;
            } else if (s.charAt(1) == '?') {
                q++;
            }
            if (s.equals("??")) {
                free++;
            } else if (s.charAt(0) == s.charAt(1)) {
                any_bad_poss = false;
            }
        }

        int w_needed = n - w;
        if (w_needed > q || w_needed < 0) {
            System.out.println(0);
            return;
        }

        int num_bad_poss;
        if (any_bad_poss) {
            num_bad_poss = pow(2, free, MOD);
            if (wb_poss) {
                num_bad_poss--;
            }
            if (bw_poss) {
                num_bad_poss--;
            }
        } else {
            num_bad_poss = 0;
        }

        System.out.println((choose(q, w_needed, MOD) - num_bad_poss + MOD) % MOD);
    }

    private static int egcd(int a, int b) {
        if (a == 0) {
            return b;
        }
        return egcd(b % a, a);
    }

    private static int modinv(int a, int m) {
        int g = egcd(a, m);
        if (g != 1) {
            throw new RuntimeException("modular inverse does not exist");
        }
        return (int) ((long) xgcd(a, m)[1] % m + m) % m;
    }

    private static int[] xgcd(int a, int b) {
        if (a == 0) {
            return new int[]{b, 0, 1};
        }
        int[] result = xgcd(b % a, a);
        int g = result[0];
        int y = result[1];
        int x = result[2];
        return new int[]{g, x - (b / a) * y, y};
    }

    private static int choose(int n, int k, int p) {
        if (k == 0 || n < k) {
            return 1;
        }
        int x = 1;
        for (int i = 0; i < k; i++) {
            x = (int) ((long) x * (n - i) % p);
            int d = i + 1;
            x = (int) ((long) x * modinv(d, p) % p);
        }
        return x;
    }

    private static int pow(int base, int exp, int mod) {
        int result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) {
                result = (int) ((long) result * base % mod);
            }
            exp >>= 1;
            base = (int) ((long) base * base % mod);
        }
        return result;
    }
}

