import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.util.Arrays;

public class Main {

    public static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }

    public static void main(String[] args) throws Exception {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(reader.readLine().trim());

        int[][] p = new int[n][2];
        for (int i = 0; i < n; i++) {
            String[] parts = reader.readLine().trim().split("\\s+");
            p[i][0] = Integer.parseInt(parts[0]);
            p[i][1] = Integer.parseInt(parts[1]);
        }

        int ans = 0;
        int cnt = 0;
        int[][] r = new int[n][n];
        int[] q = new int[n];

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                int dx = Math.abs(p[i][0] - p[j][0]);
                int dy = Math.abs(p[i][1] - p[j][1]);
                if (gcd(dx, dy) % 4 == 0) {
                    cnt++;
                    r[i][j] = 1;
                    q[i]++;
                    ans += n - 2;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 1; j < n; j++) {
                if (r[i][j] == 1) {
                    ans -= q[j] * 2;
                }
            }
        }

        System.out.println(ans);
    }
}

import java.io.*;
import java.util.*;

public class Main {
    private static int N;
    private static Scanner sc;
    private static PrintWriter out;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        sc = new Scanner(reader);
        out = new PrintWriter(System.out);

        N = sc.nextInt();
        while (N > 0) {
            solve();
            N--;
        }
        out.flush();
    }

    private static void solve() throws IOException {
        int n = sc.nextInt();
        int m = sc.nextInt();
        int k = sc.nextInt();

        int b_t = n % m;
        int b_p = n / m + 1;
        int next_b = 1;
        int next_s = 1;

        if (b_t == 0) {
            for (int i = 0; i < k; i++) {
                for (int j = 0; j < m; j++) {
                    out.print(n / m + " ");
                    for (int play = 0; play < n / m; play++) {
                        out.print(next_b + " ");
                        if (next_b == n) {
                            next_b = 1;
                        } else {
                            next_b++;
                        }
                    }
                    out.println();
                }
            }
        } else {
            for (int i = 0; i < k; i++) {
                for (int j = 0; j < b_t; j++) {
                    out.print(b_p + " ");
                    for (int play = 0; play < b_p; play++) {
                        out.print(next_b + " ");
                        if (next_b == n) {
                            next_b = 1;
                        } else {
                            next_b++;
                        }
                    }
                    out.println();
                }
                next_s = next_b;
                for (int j = 0; j < m - b_t; j++) {
                    out.print(n / m + " ");
                    for (int play = 0; play < n / m; play++) {
                        out.print(next_s + " ");
                        if (next_s == n) {
                            next_s = 1;
                        } else {
                            next_s++;
                        }
                    }
                    out.println();
                }
            }
        }
        out.println();
    }

    static class Scanner {
        private BufferedReader reader;
        private StringTokenizer tokenizer;

        public Scanner(BufferedReader reader) {
            this.reader = reader;
            try {
                readLine();
            } catch (IOException e) {
                e.printStackTrace();
            }
        }

        private void readLine() throws IOException {
            String line = reader.readLine();
            if (line != null && !line.isEmpty()) {
                tokenizer = new StringTokenizer(line);
            } else {
                tokenizer = null;
            }
        }

        public boolean hasNext() {
            return tokenizer != null && tokenizer.hasMoreTokens();
        }

        private String next() throws IOException {
            if (!hasNext()) {
                readLine();
                return next();
            }
            return tokenizer.nextToken();
        }

        public int nextInt() throws IOException {
            return Integer.parseInt(next());
        }

        public long nextLong() throws IOException {
            return Long.parseLong(next());
        }

        public double nextDouble() throws IOException {
            return Double.parseDouble(next());
        }

        public int[] readArray(int n) throws IOException {
            int[] a = new int[n];
            for (int i = 0; i < n; i++) {
                a[i] = nextInt();
            }
            return a;
        }

        public String nextLine() throws IOException {
            StringBuilder sb = new StringBuilder();
            while (hasNext()) {
                sb.append(next());
                if (!hasNext()) break;
                sb.append(" ");
            }
            readLine();
            return sb.toString().trim();
        }
    }
}

