            writer.WriteLine(s / ((n + 2) / 2));
        }
    }

    static List<int> NextLargerElement(List<int> arr, int n, bool f)
    {
        var s = new Stack<int>();
        var ans = new int[n];
        for (int i = 0; i < n; i++)
        {
            while (s.Count > 0 && arr[s.Peek()] < arr[i])
            {
                s.Pop();
            }
            if (s.Count > 0)
            {
                ans[i] = s.Peek();
            }
            s.Push(i);
        }
        if (f)
        {
            for (int i = 0; i < n; i++)
            {
                if (ans[i] != -1)
                {
                    ans[i] = n - 1 - ans[i];
                }
            }
        }
        return new List<int>(ans);
    }

    static int Dfs(int i, List<List<int>> adj, int p, int ans)
    {
        bool f = true;
        int a1 = 0;
        foreach (int j in adj[i])
        {
            if (j != p)
            {
                a1 += Dfs(j, adj, i, ans + 1);
                f = false;
            }
        }
        if (f)
        {
            a1 += ans * (ans - 1) / 2;
        }
        return a1;
    }
}

