                    for (int l = 0; l < n; l++)
                    {
                        int mod = ar[l] % 3;
                        int mn = int.MaxValue;
                        while (mod <= ar[l] && mod <= 9)
                        {
                            if (mod3[mod][0] == 1)
                            {
                                mn = Math.Min((ar[l] - mod) / 3, mn);
                            }
                            mod += 3;
                        }
                        mx = Math.Max(mx, mn);
                    }
                    if (mx == int.MaxValue)
                    {
                        continue;
                    }
                    ans = Math.Min(ans, mx + j + k);
                }
            }
            Console.WriteLine(ans);
        }
    }

