using System;
using System.IO;

class Program
{
    const int Mod = 998244353;

    static (int, int, int) Egcd(int a, int b)
    {
        if (a == 0)
            return (b, 0, 1);
        var (g, y, x) = Egcd(b % a, a);
        return (g, x - (b / a) * y, y);
    }

    static int Modinv(int a, int m)
    {
        var (g, x, _) = Egcd(a, m);
        if (g != 1)
            throw new InvalidOperationException("modular inverse does not exist");
        return (x % m + m) % m;
    }

    static int Choose(int n, int k, int p)
    {
        if (k == 0 || n < k)
            return 1;
        int x = 1;
        for (int i = 0; i < k; i++)
        {
            x = (x * (n - i) % p);
            int d = i + 1;
            x = (x * Modinv(d, p)) % p;
        }
        return x;
    }

    static void Solve()
    {
        using var reader = new StreamReader(Console.OpenStandardInput());
        string input = reader.ReadLine();
        int n = int.Parse(input);

        bool wbPoss = true;
        bool bwPoss = true;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        bool anyBadPoss = true;

        for (int i = 0; i < n; i++)
        {
            input = reader.ReadLine();
            if (input[0] == 'B')
            {
                b++;
                wbPoss = false;
            }
            else if (input[0] == 'W')
            {
                w++;
                bwPoss = false;
            }
            else if (input[0] == '?')
            {
                q++;
            }

            if (input[1] == 'B')
            {
                b++;
                bwPoss = false;
            }
            else if (input[1] == 'W')
            {
                w++;
                wbPoss = false;
            }
            else if (input[1] == '?')
            {
                q++;
            }

            if (input == "??" || input[0] == input[1])
            {
                anyBadPoss = false;
            }
        }

        int wNeeded = n - w;
        if (wNeeded > q || wNeeded < 0)
        {
            Console.WriteLine(0);
            return;
        }

        int numBadPoss;
        if (anyBadPoss)
        {
            numBadPoss = Pow(2, free, Mod);
            if (wbPoss)
                numBadPoss--;
            if (bwPoss)
                numBadPoss--;
        }
        else
        {
            numBadPoss = 0;
        }

        Console.WriteLine((Choose(q, wNeeded, Mod) - numBadPoss + Mod) % Mod);
    }

    static int Pow(int baseNum, int exp, int mod)
    {
        long result = 1;
        while (exp > 0)
        {
            if ((exp & 1) == 1)
                result = (result * baseNum) % mod;
            exp >>= 1;
            baseNum = (baseNum * baseNum) % mod;
        }
        return (int)(result % Mod);
    }

    static void Main()
    {
        Solve();
    }
}

