    const int BUFSIZE = 8192;

    class FastIO
    {
        private Stream fd;
        private byte[] buffer;
        private bool writable;

        public FastIO(Stream file)
        {
            fd = file;
            buffer = new byte[0];
            writable = file != Console.OpenStandardInput();
        }

        public string Read()
        {
            var b = new List<byte>();
            while (true)
            {
                byte[] buf = new byte[BUFSIZE];
                int n = fd.Read(buf, 0, BUFSIZE);
                if (n == 0) break;
                b.AddRange(buf.Take(n));
            }
            return System.Text.Encoding.UTF8.GetString(b.ToArray());
        }

        public string ReadLine()
        {
            var b = new List<byte>();
            while (true)
            {
                byte[] buf = new byte[BUFSIZE];
                int n = fd.Read(buf, 0, BUFSIZE);
                if (n == 0) break;
                b.AddRange(buf.Take(n));
                if (buf.Contains((byte)'\n')) break;
            }
            return System.Text.Encoding.UTF8.GetString(b.ToArray());
        }

        public void Flush()
        {
            if (writable)
            {
                Console.OpenStandardOutput().Write(buffer);
                buffer = new byte[0];
            }
        }
    }

    class IOWrapper
    {
        private StreamReader buffer;
        private bool writable;

        public IOWrapper(Stream file)
        {
            buffer = new StreamReader(file, System.Text.Encoding.UTF8, false, BUFSIZE, true);
            writable = file != Console.OpenStandardInput();
        }

        public string Read()
        {
            return buffer.ReadLine().TrimEnd('\n');
        }

        public string ReadLine()
        {
            return buffer.ReadLine();
        }

        public void Flush()
        {
            if (writable)
            {
                Console.Out.Flush();
