    {
        int n = sc.NextInt();
        int m = sc.NextInt();
        int k = sc.NextInt();

        int b_t = n % m;
        int b_p = n / m + 1;
        int next_b = 1;
        int next_s = 1;

        if (b_t == 0)
        {
            for (int i = 0; i < k; i++)
            {
                for (int j = 0; j < m; j++)
                {
                    outStream.Write($"{n / m} ");
                    for (int play = 0; play < n / m; play++)
                    {
                        outStream.Write($"{next_b} ");
                        if (next_b == n)
                        {
                            next_b = 1;
                        }
                        else
                        {
                            next_b++;
                        }
                    }
                    outStream.WriteLine();
                }
            }
        }
        else
        {
            for (int i = 0; i < k; i++)
            {
                for (int j = 0; j < b_t; j++)
                {
                    outStream.Write($"{n / m + 1} ");
                    for (int play = 0; play < b_p; play++)
                    {
                        outStream.Write($"{next_b} ");
                        if (next_b == n)
                        {
                            next_b = 1;
                        }
                        else
                        {
                            next_b++;
                        }
                    }
                    outStream.WriteLine();
                }
                next_s = next_b;
                for (int j = 0; j < m - b_t; j++)
                {
                    outStream.Write($"{n / m} ");
                    for (int play = 0; play < b_p - 1; play++)
                    {
                        outStream.Write($"{next_s} ");
                        if (next_s == n)
                        {
                            next_s = 1;
                        }
                        else
                        {
                            next_s++;
                        }
                    }
                    outStream.WriteLine();
                }
            }
        }
        outStream.WriteLine();
    }

    class Scanner
    {
        private System.IO.TextReader reader;
        private Queue<string> buffer;

        public Scanner(System.IO.TextReader reader)
        {
            this.reader = reader;
            buffer = new Queue<string>();
        }

        public string Next()
        {
            if (buffer.Count == 0)
            {
                string line = reader.ReadLine();
                if (line != null)
                {
                    foreach (var token in line.Split(new[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries))
                    {
                        buffer.Enqueue(token);
                    }
                }
            }
            return buffer.Dequeue();
        }

        public int NextInt()
        {
            return int.Parse(Next());
        }

        public long NextLong()
        {
            return long.Parse(Next());
        }

        public double NextDouble()
        {
            return double.Parse(Next());
        }

        public int[] ReadArray(int n)
        {
            int[] a = new int[n];
            for (int i = 0; i < n; i++)
            {
                a[i] = NextInt();
            }
            return a;
        }

        public string NextLine()
        {
            return reader.ReadLine();
        }
    }
}

