            dp1[num + 1] = (dp1[num + 1] * 2 % MOD + dp1[num]) % MOD;
            if num > 0 {
                dp2[num - 1] = (dp2[num - 1] * 2 % MOD + dp1[num - 1]) % MOD;
            }
            dp2[num + 1] = (dp2[num + 1] * 2) % MOD;
        }

        let mut ans = 0;
