fn next_larger_element(arr: &[i32], n: usize, f: bool) -> Vec<i32> {
    let mut s = Vec::new();
    let mut ans = vec![-1; n];
    for i in 0..n {
        while !s.is_empty() && arr[s[s.len() - 1]] < arr[i] {
            s.pop();
        }
        if let Some(&top) = s.last() {
            ans[i] = top as i32;
        }
        s.push(i);
    }
    if f {
        for i in 0..n {
            if ans[i] != -1 {
                ans[i] = (n - 1 - ans[i]) as i32;
            }
        }
    }
    ans
}

fn dfs(i: usize, adj: &[Vec<usize>], p: usize, ans: usize) -> usize {
    let mut f = true;
    let mut a1 = 0;
    for &j in &adj[i] {
        if j != p {
            a1 += dfs(j, adj, i, ans + 1);
            f = false;
        }
    }
    if f {
        a1 += ans * (ans - 1) / 2;
    }
    a1
}

