const ARRAY_SIZE: usize = 2022;
static mut A: [i64; ARRAY_SIZE] = [0; ARRAY_SIZE];
static mut POS: i64 = 0;
static mut ANS: Vec<i64> = Vec::new();

fn go_func() {
    unsafe {
        ANS.push(POS);
        for i in 1..=POS / 2 {
            A.swap(i as usize, (POS - i + 1) as usize);
        }
    }
}

fn solve() -> io::Result<()> {
    let mut input = String::new();
    io::stdin().read_line(&mut input)?;
    let n: i64 = input.trim().parse().unwrap();

    for _ in 0..n {
        input.clear();
        io::stdin().read_line(&mut input)?;
        unsafe {
            A[(n - 1) as usize] = input.trim().parse().unwrap();
        }
    }

    unsafe {
        ANS.clear();
        for i in 1..=n {
            if i % 2 != A[i as usize] % 2 {
                writeln!(io::stdout(), "-1")?;
                return Ok(());
            }
        }

        for i in (2..=n).rev().step_by(2) {
            for j in 1..=n {
                if A[j as usize] == i {
                    POS = j;
                    break;
                }
            }
            go_func();
            for j in 1..=n {
                if A[j as usize] == i - 1 {
                    POS = j - 1;
                    break;
                }
            }
            go_func();
            for j in 1..=n {
                if A[j as usize] == i - 1 {
                    POS = j + 1;
                    break;
                }
            }
            go_func();
            POS = 3;
            go_func();
            POS = i;
            go_func();
        }

        writeln!(io::stdout(), "{}", ANS.len())?;
        for &v in unsafe { &ANS } {
            write!(io::stdout(), "{} ", v)?;
        }
        writeln!(io::stdout())?;
    }
    Ok(())
}

