fn solve(n: i64, k: i64, mut x: i64, s: &str) -> String {
    let mut vec = Vec::new();
    let mut ans = Vec::new();
    let mut cnt = 0;
    for c in s.chars() {
        if c == '*' {
            cnt += 1;
        } else {
            if cnt > 0 {
                vec.push(cnt * k as usize);
            }
            cnt = 0;
        }
    }
    if cnt > 0 {
        vec.push(cnt * k as usize);
    }

    for &v in vec.iter().rev() {
        ans.push((x % (v as i64 + 1)) as usize);
        x /= v as i64 + 1;
    }

    let sr = ans.len();
    for _ in sr..vec.len() {
