const MOD: i64 = 998244353;

fn egcd(a: i64, b: i64) -> (i64, i64, i64) {
    if a == 0 {
        return (b, 0, 1);
    }
    let (g, y, x) = egcd(b % a, a);
    (g, x - (b / a) * y, y)
}

fn modinv(a: i64, m: i64) -> i64 {
    let (g, x, _) = egcd(a, m);
    if g != 1 {
        panic!("modular inverse does not exist");
    }
    (x % m + m) % m
}

fn choose(n: i64, k: i64, p: i64) -> i64 {
    if k == 0 || n < k {
        return 1;
    }
    let mut x = 1;
    for i in 0..k {
        x = x * (n - i) % p;
        let d = i + 1;
        x = x * modinv(d, p) % p;
    }
    x
}

fn pow(base: i64, exp: i64, modulus: i64) -> i64 {
    let mut result = 1;
    let mut base = base;
    let mut exp = exp;
    while exp > 0 {
        if exp % 2 == 1 {
            result = result * base % modulus;
        }
        exp >>= 1;
        base = base * base % modulus;
    }
    result
}

fn solve() {
    let stdin = io::stdin();
    let mut lines = stdin.lock().lines();

    let n: i64 = lines.next().unwrap().expect("Failed to read line").trim().parse().unwrap();

    let mut wb_poss = true;
    let mut bw_poss = true;
    let mut w = 0;
    let mut b = 0;
    let mut q = 0;
    let mut free = 0;
    let mut any_bad_poss = true;

    for _ in 0..n {
        let line = lines.next().unwrap().expect("Failed to read line").trim().to_string();
        if line.starts_with('B') {
            b += 1;
            wb_poss = false;
        } else if line.starts_with('W') {
            w += 1;
            bw_poss = false;
        } else if line.starts_with('?') {
            q += 1;
        }
        if line.ends_with('B') {
            b += 1;
            bw_poss = false;
        } else if line.ends_with('W') {
            w += 1;
            wb_poss = false;
        } else if line.ends_with('?') {
            q += 1;
        }
        if line == "??" {
            free += 1;
        } else if line.starts_with(line.chars().nth(1).unwrap()) {
            any_bad_poss = false;
        }
    }

    let w_needed = n - w;
    if w_needed > q || w_needed < 0 {
        println!("0");
        return;
    }

    let mut num_bad_poss: i64;
    if any_bad_poss {
        num_bad_poss = pow(2, free, MOD);
        if wb_poss {
            num_bad_poss -= 1;
        }
        if bw_poss {
            num_bad_poss -= 1;
        }
    } else {
        num_bad_poss = 0;
    }

    println!("{}", (choose(q, w_needed, MOD) - num_bad_poss + MOD) % MOD);
}

