use std::io::{self, BufRead, Write};

struct Scanner {
    reader: io::BufReader<io::Stdin>,
    buffer: Vec<String>,
}

impl Scanner {
    fn new(reader: io::BufReader<io::Stdin>) -> Self {
        Scanner {
            reader,
            buffer: vec![],
        }
    }

    fn next(&mut self) -> String {
        if self.buffer.is_empty() {
            let mut line = String::new();
            self.reader.read_line(&mut line).expect("Failed to read line");
            self.buffer = line.split_whitespace().map(|s| s.to_string()).collect();
        }
        self.buffer.remove(0)
    }

    fn next_int(&mut self) -> i32 {
        self.next().parse::<i32>().expect("Failed to parse integer")
    }

    fn next_long(&mut self) -> i64 {
        self.next().parse::<i64>().expect("Failed to parse long")
    }

    fn next_double(&mut self) -> f64 {
        self.next().parse::<f64>().expect("Failed to parse double")
    }

    fn read_array(&mut self, n: usize) -> Vec<i32> {
        (0..n).map(|_| self.next_int()).collect()
    }

    fn next_line(&mut self) -> String {
        let mut line = String::new();
        self.reader.read_line(&mut line).expect("Failed to read line");
        line.trim().to_string()
    }
}

