    let b_p = n / m + 1;
    let mut next_b = 1;

    if b_t == 0 {
        for _ in 0..k {
            for _ in 0..m {
                write!(out, "{} ", n / m).unwrap();
                for _ in 0..n / m {
                    write!(out, "{} ", next_b).unwrap();
                    if next_b == n {
                        next_b = 1;
                    } else {
                        next_b += 1;
