const int BUFSIZE = 8192;

class FastIO {
public:
    std::istream& reader;
    std::ostream& writer;

    FastIO(std::istream& input, std::ostream& output) : reader(input), writer(output) {}

    std::string Read() {
        std::ostringstream buffer;
        char b[BUFSIZE];
        while (reader.read(b, BUFSIZE)) {
            buffer.write(b, BUFSIZE);
        }
        if (!reader.eof()) {
            buffer << reader.rdbuf();
        }
        return buffer.str();
    }

    std::string ReadLine() {
        std::string line;
        std::getline(reader, line);
        return line;
    }

    void Write(const std::string& s) {
        writer << s;
    }

    void Flush() {
        writer.flush();
    }
};

