        } else if (s[1] == 'W') {
            w++;
            wb_poss = false;
        } else if (s[1] == '?') {
            q++;
        }
        if (s == "??" && s[0] != s[1]) {
            free++;
        } else if (s[0] == s[1]) {
            any_bad_poss = false;
        }
    }

    int w_needed = n - w;
    if (w_needed > q || w_needed < 0) {
