    FastIO(std::istream* file) : fd(file), writable(file != &std::cin) {}

    std::string Read() {
        std::string result;
        char buf[BUFSIZE];
        while (fd->read(buf, BUFSIZE)) {
            result.append(buf, BUFSIZE);
        }
        if (fd->eof()) {
            result.append(buf, fd->gcount());
        }
        return result;
    }

    std::string ReadLine() {
        std::string line;
        std::getline(*fd, line);
        return line;
    }

    void Flush() {
        if (writable) {
            std::cout << buffer.str();
            buffer.clear();
        }
    }
};

