let BUFSIZE = 8192

class FastIO {
    private let reader: StreamReader
    private let writer: StreamWriter

    init(file: FileHandle) {
        self.reader = StreamReader(file: file, bufferSize: BUFSIZE)
        self.writer = StreamWriter(file: file, bufferSize: BUFSIZE)
    }

    func read() -> String {
        var buffer = ""
        while let line = reader.nextLine() {
            buffer += line
        }
        return buffer
    }

    func readLine() -> String? {
        return reader.nextLine()
    }

    func write(_ string: String) {
        writer.write(string)
    }

    func flush() {
        writer.flush()
    }
}

class StreamReader {
    private let file: FileHandle
    private let bufferSize: Int
    private var buffer: Data

    init(file: FileHandle, bufferSize: Int) {
        self.file = file
        self.bufferSize = bufferSize
        self.buffer = Data(capacity: bufferSize)
        refillBuffer()
    }

    func nextLine() -> String? {
        while let index = buffer.firstIndex(of: 10) { // ASCII for '\n'
            let lineData = buffer.prefix(upTo: index)
            buffer.removeSubrange(lineData.startIndex...index)
            return String(data: lineData, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines)
        }

        if !buffer.isEmpty {
            let remainingString = String(data: buffer, encoding: .utf8)?.trimmingCharacters(in: .whitespacesAndNewlines)
            buffer.removeAll()
            return remainingString
        }

        return nil
    }

    private func refillBuffer() {
        let data = file.readData(ofLength: bufferSize)
        if !data.isEmpty {
            buffer.append(data)
        }
    }
}

class StreamWriter {
    private let file: FileHandle
    private let bufferSize: Int
    private var buffer: Data

    init(file: FileHandle, bufferSize: Int) {
        self.file = file
        self.bufferSize = bufferSize
        self.buffer = Data(capacity: bufferSize)
    }

    func write(_ string: String) {
        if let data = string.data(using: .utf8) {
            buffer.append(data)
            if buffer.count > bufferSize {
                flush()
            }
        }
    }

    func flush() {
        file.write(buffer)
        buffer.removeAll()
    }
}

