import Foundation

let mod = 998244353

func egcd(_ a: Int, _ b: Int) -> (Int, Int, Int) {
    if a == 0 {
        return (b, 0, 1)
    }
    let (g, y, x) = egcd(b % a, a)
    return (g, x - (b / a) * y, y)
}

func modinv(_ a: Int, _ m: Int) -> Int {
    let (g, x, _) = egcd(a, m)
    if g != 1 {
        fatalError("modular inverse does not exist")
    }
    return (x % m + m) % m
}

func choose(_ n: Int, _ k: Int, _ p: Int) -> Int {
    if k == 0 || n < k {
        return 1
    }
    var x = 1
    for i in 0..<k {
        x = x * (n - i) % p
        let d = i + 1
        x = x * modinv(d, p) % p
    }
    return x
}

func solve() {
    guard let input = readLine(), let n = Int(input) else { return }

    var wb_poss = true
    var bw_poss = true
    var w = 0
    var b = 0
    var q = 0
    var free = 0
    var any_bad_poss = true

    for _ in 0..<n {
        guard let s = readLine() else { return }
        if s.first == "B" {
            b += 1
            wb_poss = false
        } else if s.first == "W" {
            w += 1
            bw_poss = false
        } else if s.first == "?" {
            q += 1
        }
        if s.last == "B" {
            b += 1
            bw_poss = false
        } else if s.last == "W" {
            w += 1
            wb_poss = false
        } else if s.last == "?" {
            q += 1
        }
        if s == "??" {
            free += 1
        } else if s.first == s.last {
            any_bad_poss = false
        }
    }

    let w_needed = n - w
    if w_needed > q || w_needed < 0 {
        print(0)
        return
    }

    var num_bad_poss: Int
    if any_bad_poss {
        num_bad_poss = pow(2, free, mod)
        if wb_poss {
            num_bad_poss -= 1
        }
        if bw_poss {
            num_bad_poss -= 1
        }
    } else {
        num_bad_poss = 0
    }

    print((choose(q, w_needed, mod) - num_bad_poss + mod) % mod)
}

func pow(_ base: Int, _ exp: Int, _ mod: Int) -> Int {
    var result = 1
    var exp = exp
    var base = base

    while exp > 0 {
        if exp & 1 == 1 {
            result = result * base % mod
        }
        exp >>= 1
        base = base * base % mod
    }

    return result
}

