import sys

class FastReader:
    def __init__(self):
        self._sr = sys.stdin
        self._current_line_tokens = []
        self._token_index = 0

    def _read_next_line_tokens(self):
        line = self._sr.readline().strip()
        if line:
            self._current_line_tokens = line.split()
            self._token_index = 0
        else:
            self._current_line_tokens = []

    def next(self):
        if self._token_index >= len(self._current_line_tokens):
            self._read_next_line_tokens()
        token = self._current_line_tokens[self._token_index]
        self._token_index += 1
        return token

    def next_int(self):
        return int(self.next())

    def next_long(self):
        return int(self.next())  # Python's int can handle longs, so we use int here.

    def next_double(self):
        return float(self.next())

    def next_line(self):
        if self._token_index >= len(self._current_line_tokens):
            self._read_next_line_tokens()
        result = ' '.join(self._current_line_tokens[self._token_index:])
        self._token_index = len(self._current_line_tokens)
        return result

def reverse(arr, r):
