class FastIO:
    def __init__(self, stream):
        self._stream = stream
        self._buffer = bytearray()
        self._read_buffer = bytearray(8192)
        self._writable = stream.writable()

    def read_to_end(self):
        while True:
            bytes_read = self._stream.readinto(self._read_buffer)
            if bytes_read == 0:
                break
            self._buffer.extend(self._read_buffer[:bytes_read])
        return self._buffer.decode('ascii')

    def readline(self):
        line = bytearray()
        while True:
            b = self._stream.read(1)
            if not b or b == b'\n':
                break
            line.extend(b)
        return line.decode('ascii').rstrip('\n')

    def __del__(self):
        try:
            self._buffer.clear()
            self._stream.close()
        except Exception as e:
            pass

