class FastIO:
    BUFSIZE = 8192

    def __init__(self, input_stream=sys.stdin.buffer, output_stream=sys.stdout.buffer):
        self.input_stream = input_stream
        self.output_stream = output_stream
        self.buffer = bytearray(self.BUFSIZE)
        self.buffer_size = 0
        self.buffer_index = 0

    def read_line(self):
        ms = bytearray()
        while True:
            if self.buffer_index >= self.buffer_size:
                self.buffer_size = self.input_stream.readinto(self.buffer)
                self.buffer_index = 0
            if self.buffer_size == 0:
                break

            newline_index = self.buffer.find(b'\n', self.buffer_index)
            if newline_index >= 0:
                ms.extend(self.buffer[self.buffer_index:newline_index + 1])
                self.buffer_index = newline_index + 1
                break
            else:
                ms.extend(self.buffer[self.buffer_index:self.buffer_size])
                self.buffer_index = self.buffer_size

        return ms.decode('ascii').rstrip('\r\n')

    def write_line(self, value):
        bytes_value = (str(value) + '\n').encode('ascii')
        self.output_stream.write(bytes_value)

