function main() {
    rl.question('', (tInput) => {
        const t = parseInt(tInput, 10);

        let testCaseCount = 0;
        const readNextTestCase = () => {
            if (testCaseCount >= t) {
                rl.close();
                return;
            }

            rl.question('', (inputLine) => {
                const input = inputLine.split(' ');
                const n = parseInt(input[0], 10);
                const m = parseInt(input[1], 10);

                const nums: boolean[] = new Array(n).fill(false);
                let edgesRead = 0;

                const readEdge = () => {
                    if (edgesRead >= m) {
                        solve(nums, n);
                        testCaseCount++;
                        readNextTestCase();
                        return;
                    }

                    rl.question('', (edgeLine) => {
                        const edgeInput = edgeLine.split(' ');
                        const b = parseInt(edgeInput[1], 10) - 1;
                        nums[b] = true;
                        edgesRead++;
                        readEdge();
                    });
                };

                readEdge();
            });
        };

        readNextTestCase();
    });
}

