    for (let i = 0; i < n; i++) {
        if (!nums[i]) {
            notMiddleNode = i;
            break;
        }
    }

    for (let i = 0; i < n; i++) {
        if (i !== notMiddleNode) {
            console.log(`${notMiddleNode + 1} ${i + 1}`);
        }
    }
}

