import * as readline from 'readline';

class FastReader {
    private rl: readline.Interface;
    private currentLineTokens: string[] = [];
    private tokenIndex: number = 0;

    constructor() {
        this.rl = readline.createInterface({
            input: process.stdin,
            output: process.stdout,
            terminal: false
        });
    }

    private readNextLineTokens(): void {
        this.currentLineTokens = this.rl.line?.split(/\s+/).filter(token => token.length > 0) || [];
        this.tokenIndex = 0;
    }

    public next(): string {
        if (this.tokenIndex >= this.currentLineTokens.length) {
            this.readNextLineTokens();
        }
        return this.currentLineTokens[this.tokenIndex++];
    }

    public nextInt(): number {
        return parseInt(this.next(), 10);
    }

    public nextLong(): number {
        return parseFloat(this.next());
    }

    public nextDouble(): number {
        return parseFloat(this.next());
    }

    public nextLine(): string {
        if (this.tokenIndex >= this.currentLineTokens.length) {
            this.readNextLineTokens();
        }
        const result = this.currentLineTokens.slice(this.tokenIndex).join(' ');
        this.tokenIndex = this.currentLineTokens.length;
        return result;
    }
}

function reverse(arr: number[], r: number): void {
    for (let i = 0; i <= Math.floor(r / 2); i++) {
        const l = i, h = r - i;
        [arr[l], arr[h]] = [arr[h], arr[l]];
    }
}

