class FastIO {
    private readonly stream: NodeJS.ReadableStream;
    private readonly buffer: Buffer = Buffer.alloc(0);
    private readonly readBuffer: Buffer = Buffer.alloc(8192);

    constructor(stream: NodeJS.ReadableStream) {
        this.stream = stream;
    }

    public async readToEnd(): Promise<string> {
        while (true) {
            const bytesRead = await new Promise<number>((resolve, reject) => {
                this.stream.read(this.readBuffer, 0, this.readBuffer.length, null, (err, bytesRead) => {
                    if (err) reject(err);
                    else resolve(bytesRead || 0);
                });
            });
            if (bytesRead === 0) break;
            this.buffer = Buffer.concat([this.buffer, this.readBuffer.subarray(0, bytesRead)]);
        }
        return this.buffer.toString('ascii');
    }

    public async readLine(): Promise<string> {
        const line: string[] = [];
        while (true) {
            const b = await new Promise<number>((resolve, reject) => {
                this.stream.read(1, null, null, null, (err, bytesRead, buffer) => {
                    if (err) reject(err);
                    else resolve(bytesRead ? buffer[0] : -1);
                });
            });
            if (b === -1 || b === 10) break;
            line.push(String.fromCharCode(b));
        }
        return line.join('');
    }

    public dispose(): void {
        this.stream.destroy();
    }
}

