            for (let i = 0; i < n; i++) {
                const line = await new Promise((resolve) => rl.once('line', resolve)).trim();
                for (let j = 0; j < m; j++) {
                    const ch = line[j];
                    d[i][j] = ch === 'R' ? -1 : (ch === 'U' ? -2 : (ch === 'L' ? -3 : -4));
                }
            }

            let r = 0;
            let pos: [number, number] = [0, 0];

            for (let i = 0; i < n; i++) {
                for (let j = 0; j < m; j++) {
                    let a = i, b = j, p = d[i][j], c = 0;
                    const st: [number, number][] = [];

                    while (p < 0) {
                        d[a][b] = 0;
                        st.push([a, b]);
                        if (p === -1) b++;
                        else if (p === -2) a--;
                        else if (p === -3) b--;
                        else a++;
                        c++;
                        if (a >= 0 && a < n && b >= 0 && b < m)
                            p = d[a][b];
                        else {
                            for (let ii = 0; ii < st.length; ii++) {
                                const [tuple1, tuple2] = st[ii];
                                d[tuple1][tuple2] = c - ii;
