class FastIO {
    private static readonly BUFSIZE = 8192;
    private inputStream: NodeJS.ReadableStream;
    private outputStream: NodeJS.WritableStream;
    private buffer: Buffer;
    private bufferSize: number;
    private bufferIndex: number;

    constructor(inputStream: NodeJS.ReadableStream, outputStream: NodeJS.WritableStream) {
        this.inputStream = inputStream;
        this.outputStream = outputStream;
        this.buffer = Buffer.alloc(FastIO.BUFSIZE);
        this.bufferSize = 0;
        this.bufferIndex = 0;
    }

    public async readLine(): Promise<string> {
        const ms: number[] = [];
        while (true) {
            if (this.bufferIndex >= this.bufferSize) {
                this.bufferSize = await new Promise((resolve, reject) => {
                    this.inputStream.read(FastIO.BUFSIZE, 0, FastIO.BUFSIZE, null, (err, bytesRead) => {
                        if (err) reject(err);
                        resolve(bytesRead ?? 0);
                    });
                });
                this.bufferIndex = 0;
            }
            if (this.bufferSize === 0) break;

            const newlineIndex = this.buffer.indexOf(10, this.bufferIndex);
            if (newlineIndex >= 0) {
                for (let i = this.bufferIndex; i <= newlineIndex; i++) {
                    ms.push(this.buffer[i]);
                }
                this.bufferIndex = newlineIndex + 1;
                break;
            } else {
                for (let i = this.bufferIndex; i < this.bufferSize; i++) {
                    ms.push(this.buffer[i]);
                }
                this.bufferIndex = this.bufferSize;
            }
        }
        return Buffer.from(ms).toString('ascii').trimEnd('\r', '\n');
    }

    public writeLine(value: number): void {
        const bytes = Buffer.from(`${value}\n`, 'ascii');
        this.outputStream.write(bytes);
    }
}

