func NewFastReader() *FastReader {
	return &FastReader{
		scanner: bufio.NewScanner(os.Stdin),
	}
}

func (fr *FastReader) NextLine() string {
	fr.scanner.Scan()
	return fr.scanner.Text()
}

func (fr *FastReader) ReadNextLineTokens() {
	line := fr.NextLine()
	if line == "" {
		fr.line = []string{}
	} else {
		fr.line = strings.Fields(line)
	}
	fr.index = 0
}

func (fr *FastReader) Next() string {
	if fr.index >= len(fr.line) {
		fr.ReadNextLineTokens()
	}
	token := fr.line[fr.index]
	fr.index++
	return token
}

func (fr *FastReader) NextInt() int {
	i, _ := strconv.Atoi(fr.Next())
	return i
}

func Reverse(a []int, r int) {
	for i := 0; i <= r/2; i++ {
		l, h := i, r-i
		a[l], a[h] = a[h], a[l]
	}
}

