const BUFSIZE = 8192

type FastIO struct {
	inputStream  *os.File
	outputStream *os.File
	buffer       []byte
	bufferSize   int
	bufferIndex  int
}

func NewFastIO(inputStream, outputStream *os.File) *FastIO {
	return &FastIO{
		inputStream:  inputStream,
		outputStream: outputStream,
		buffer:       make([]byte, BUFSIZE),
	}
}

func (fio *FastIO) ReadLine() string {
	var result []byte
	for {
		if fio.bufferIndex >= fio.bufferSize {
			n, _ := fio.inputStream.Read(fio.buffer)
			fio.bufferSize = n
			fio.bufferIndex = 0
			if n == 0 {
				break
			}
		}

		newlineIndex := -1
		for i := fio.bufferIndex; i < fio.bufferSize; i++ {
			if fio.buffer[i] == '\n' {
				newlineIndex = i
				break
			}
		}

		if newlineIndex >= 0 {
			result = append(result, fio.buffer[fio.bufferIndex:newlineIndex+1]...)
			fio.bufferIndex = newlineIndex + 1
			break
		} else {
			result = append(result, fio.buffer[fio.bufferIndex:fio.bufferSize]...)
			fio.bufferIndex = fio.bufferSize
		}
	}
	return string(result)
}

func (fio *FastIO) WriteLine(value int64) {
	fmt.Fprintf(fio.outputStream, "%d\n", value)
}

func main() {
