		if n == 2 {
			res = int64(arr[0]) * int64(arr[1])
		} else {
			res = -1
			for j := 0; j < n-1; j++ {
				product := int64(max(arr[j+1], arr[j])) * int64(min(arr[j+1], arr[j]))
				if product > res {
