const Mod = 998244353

func egcd(a, b int) (int, int, int) {
	if a == 0 {
		return b, 0, 1
	} else {
		g, y, x := egcd(b%a, a)
		return g, x - (b/a)*y, y
	}
}

func modinv(a, m int) int {
	g, x, _ := egcd(a, m)
	if g != 1 {
		panic("modular inverse does not exist")
	} else {
		return (x % m + m) % m
	}
}

func choose(n, k, p int) int {
	if k == 0 {
		return 1
	}
	var x big.Int
	x.SetInt64(int64(n))
	for y := n - 1; y > n-k; y-- {
		x.Mul(&x, big.NewInt(int64(y)))
		x.Mod(&x, big.NewInt(int64(p)))
	}
	var d big.Int
	d.SetInt64(1)
	for i := 2; i <= k; i++ {
		d.Mul(&d, big.NewInt(int64(i)))
		d.Mod(&d, big.NewInt(int64(p)))
	}
	var inv big.Int
	inv.SetInt64(int64(modinv(int(d.Int64()), p)))
	x.Mul(&x, &inv)
	x.Mod(&x, big.NewInt(int64(p)))
	return int(x.Int64())
}

func solve() {
	scanner := bufio.NewScanner(os.Stdin)
	n := 0
	if scanner.Scan() {
		fmt.Sscanf(scanner.Text(), "%d", &n)
	}

	wb_poss := n > 1
	bw_poss := n > 1
	w := 0
	b := 0
	q := 0
	free := 0
	any_bad_poss := n > 1

	for i := 0; i < n; i++ {
		scanner.Scan()
		s := scanner.Text()
		if s[0] == 'B' {
			b++
			wb_poss = false
		} else if s[0] == 'W' {
			w++
			bw_poss = false
		} else if s[0] == '?' {
			q++
		}

		if s[1] == 'B' {
			b++
			bw_poss = false
		} else if s[1] == 'W' {
			w++
			bw_poss = false
		} else if s[1] == '?' {
			q++
		}

		if s == "???" {
			free++
		} else if s[0] == s[1] {
			any_bad_poss = false
		}
	}

	w_needed := n - w
	if w_needed > q || w_needed < 0 {
		fmt.Println(0)
		return
	}

	var num_bad_poss int
	if any_bad_poss {
		twoPowerFree := big.NewInt(2).Exp(big.NewInt(int64(free)), big.NewInt(int64(free)), nil)
		num_bad_poss = int(twoPowerFree.Int64()) - (bw_poss + wb_poss)
	} else {
		num_bad_poss = 0
	}

	fmt.Println((choose(q, w_needed, Mod)-num_bad_poss+Mod)%Mod)
}

func main() {
	solve()
}

