public class Main {
    public static void main(String[] args) throws Exception {
        FastReader input = new FastReader();
        int T = input.nextInt();
        while (T-- > 0) {
            int n = input.nextInt();
            int[] a = new int[n];
            int flag = 0;
            for (int i = 0; i < n; i++) {
                a[i] = input.nextInt();
                int p = i + 1;
                if (p % 2 != a[i] % 2) {
                    flag = 1;
                }
            }
            if (flag == 1) {
                System.out.println(-1);
            } else {
                List<Integer> list = new ArrayList<>();
                for (int i = n; i > 1; i -= 2) {
                    int in1 = 0, in2 = 0;
                    for (int j = 0; j < n; j++) {
                        if (a[j] == i) in1 = j;
                        else if (a[j] == i - 1) in2 = j;
                    }
                    reverse(a, in1);
                    if (in1 > in2) {
                        in2 = in1 - in2;
                    }
                    reverse(a, in2 - 1);
                    reverse(a, in2 + 1);
                    reverse(a, 2);
                    reverse(a, i - 1);
                    list.add(in1 + 1); list.add(in2); list.add(in2 + 2); list.add(3); list.add(i);
                }
                System.out.println(list.size());
                for (int i = 0; i < list.size(); i++) {
                    System.out.print(list.get(i) + " ");
                }
                System.out.println();
            }
        }
    }

    static void reverse(int[] a, int r) {
        for (int i = 0; i <= r / 2; i++) {
            int l = i, h = r - i;
            int t = a[l];
            a[l] = a[h];
            a[h] = t;
        }
    }

    static class FastReader {
        private final BufferedReader _br;
        private String[] _currentLineTokens;
        private int _tokenIndex;

        public FastReader() {
            _br = new BufferedReader(new InputStreamReader(System.in));
            _currentLineTokens = new String[0];
            _tokenIndex = 0;
        }

        private void readNextLineTokens() throws Exception {
            _currentLineTokens = _br.readLine().split("[ \t]+");
            _tokenIndex = 0;
        }

        public String next() throws Exception {
            if (_tokenIndex >= _currentLineTokens.length)
                readNextLineTokens();
            return _currentLineTokens[_tokenIndex++];
        }

        public int nextInt() throws Exception {
            return Integer.parseInt(next());
        }

        public long nextLong() throws Exception {
            return Long.parseLong(next());
        }

        public double nextDouble() throws Exception {
            return Double.parseDouble(next());
        }

        public String nextLine() throws Exception {
            if (_tokenIndex >= _currentLineTokens.length)
                readNextLineTokens();
            StringBuilder result = new StringBuilder();
            for (int i = _tokenIndex; i < _currentLineTokens.length; i++) {
                result.append(_currentLineTokens[i]).append(" ");
            }
            _tokenIndex = _currentLineTokens.length;
            return result.toString().trim();
        }
    }
}

