            _output.print(args[i].toString());
        }
        _output.println(end);
        _output.flush();
    }

    static class FastIO extends BufferedReader implements Closeable {

        private final InputStream _stream;
        private final ByteArrayOutputStream _buffer = new ByteArrayOutputStream();
        private final byte[] _readBuffer = new byte[8192];
        private boolean _writable;

        public FastIO(InputStream stream) {
            super(new InputStreamReader(stream));
            this._stream = stream;
            this._writable = false; // Stream is not writable
        }

        @Override
        public String readToEnd() throws IOException {
            while (true) {
                int bytesRead = _stream.read(_readBuffer, 0, _readBuffer.length);
                if (bytesRead == -1) break;
                _buffer.write(_readBuffer, 0, bytesRead);
            }
            return new String(_buffer.toByteArray(), "ASCII");
        }

        @Override
        public void close() throws IOException {
            super.close();
            _stream.close();
        }
    }
}

