            int[][] d = new int[n][m];
            for (int j = 0; j < n; j++) {
                String line = scanner.nextLine().trim();
                for (int k = 0; k < m; k++) {
                    char ch = line.charAt(k);
                    d[j][k] = ch == 'R' ? -1 : (ch == 'U' ? -2 : (ch == 'L' ? -3 : -4));
                }
            }

            int r = 0;
            Pair<Integer, Integer> pos = new Pair<>(0, 0);

            for (int j = 0; j < n; j++) {
                for (int k = 0; k < m; k++) {
                    int a = j, b = k, p = d[j][k], c = 0;
                    List<Pair<Integer, Integer>> st = new ArrayList<>();
                    while (p < 0) {
                        d[a][b] = 0;
                        st.add(new Pair<>(a, b));
                        if (p == -1) b++;
                        else if (p == -2) a--;
                        else if (p == -3) b--;
                        else a++;
                        c++;
                        if (a >= 0 && a < n && b >= 0 && b < m)
                            p = d[a][b];
                        else {
                            for (int ii = 0; ii < st.size(); ii++) {
                                Pair<Integer, Integer> tuple = st.get(ii);
                                d[tuple.getKey()][tuple.getValue()] = c - ii;
                            }
                            p = -1;
                            break;
                        }
                    }

                    if (p == 0) {
                        int jj = 0, flag = 0;
                        for (int ii = 0; ii < st.size(); ii++) {
                            Pair<Integer, Integer> tuple = st.get(ii);
                            d[tuple.getKey()][tuple.getValue()] = flag == 1 ? c - jj : c - ii;
                            if (tuple.getKey() == a && tuple.getValue() == b) {
                                flag = 1;
                                jj = ii;
                            }
                        }
                    }

                    if (p > 0) {
                        for (int ii = 0; ii < st.size(); ii++) {
                            Pair<Integer, Integer> tuple = st.get(ii);
                            d[tuple.getKey()][tuple.getValue()] = p + c - ii;
                        }
                    }

                    if (d[j][k] > r) {
