        int t = Integer.parseInt(fastIO.readLine());
        for (int i = 0; i < t; i++) {
            int n = Integer.parseInt(fastIO.readLine());
            String[] input = fastIO.readLine().split(" ");
            int[] arr = new int[n];
            for (int j = 0; j < n; j++) {
                arr[j] = Integer.parseInt(input[j]);
            }
            if (n == 2) {
                fastIO.println((long) arr[0] * arr[1]);
            } else {
                long res = -1;
                for (int j = 0; j < n - 1; j++) {
                    long product = Math.max(arr[j + 1], arr[j]) * Math.min(arr[j + 1], arr[j]);
                    if (product > res) {
                        res = product;
                    }
                }
                fastIO.println(res);
            }
        }
    }

    static class FastIO {
        private static final int BUFSIZE = 8192;
        private final InputStream inputStream;
        private final OutputStream outputStream;
        private final byte[] buffer;
        private int bufferSize;
        private int bufferIndex;

        public FastIO(InputStream inputStream, OutputStream outputStream) {
            this.inputStream = inputStream;
            this.outputStream = outputStream;
            this.buffer = new byte[BUFSIZE];
            this.bufferSize = 0;
            this.bufferIndex = 0;
        }

        public String readLine() throws IOException {
            ByteArrayOutputStream ms = new ByteArrayOutputStream();
            while (true) {
                if (bufferIndex >= bufferSize) {
                    bufferSize = inputStream.read(buffer, 0, BUFSIZE);
                    bufferIndex = 0;
                }
                if (bufferSize == 0) break;

                int newlineIndex = indexOf(buffer, (byte) '\n', bufferIndex);
                if (newlineIndex >= 0) {
                    ms.write(buffer, bufferIndex, newlineIndex - bufferIndex + 1);
                    bufferIndex = newlineIndex + 1;
                    break;
                } else {
                    ms.write(buffer, bufferIndex, bufferSize - bufferIndex);
                    bufferIndex = bufferSize;
                }
            }
            return new String(ms.toByteArray()).trim();
        }

        private int indexOf(byte[] array, byte target, int start) {
            for (int i = start; i < array.length; i++) {
                if (array[i] == target) {
                    return i;
                }
            }
            return -1;
        }

        public void println(long value) throws IOException {
            String str = Long.toString(value) + "\n";
            outputStream.write(str.getBytes());
        }
    }
}

import java.math.BigInteger;
import java.util.Scanner;

public class Main {
    private static final int MOD = 998244353;

    public static void main(String[] args) {
        solve();
    }

    private static void solve() {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());
        boolean wbPoss = n > 1;
        boolean bwPoss = n > 1;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        boolean anyBadPoss = n > 1;

        for (int i = 0; i < n; i++) {
            String s = scanner.nextLine().trim();
            if (s.charAt(0) == 'B') {
                b++;
                wbPoss = false;
            } else if (s.charAt(0) == 'W') {
                w++;
                bwPoss = false;
            } else if (s.charAt(0) == '?') {
                q++;
            }

            if (s.charAt(1) == 'B') {
                b++;
                bwPoss = false;
            } else if (s.charAt(1) == 'W') {
                w++;
                wbPoss = false;
            } else if (s.charAt(1) == '?') {
                q++;
            }

            if (s.equals("??")) {
                free++;
            } else if (s.charAt(0) == s.charAt(1)) {
                anyBadPoss = false;
            }
        }

        int wNeeded = n - w;
        if (wNeeded > q || wNeeded < 0) {
            System.out.println(0);
            return;
        }

        int numBadPoss;
        if (anyBadPoss) {
            numBadPoss = (int) (modPow(2, free, MOD) - (bwPoss ? 1 : 0) - (wbPoss ? 1 : 0));
        } else {
            numBadPoss = 0;
        }

        System.out.println((choose(q, wNeeded, MOD) - numBadPoss + MOD) % MOD);
    }

    private static int[] egcd(int a, int b) {
        if (a == 0)
            return new int[]{b, 0, 1};
        else {
            int[] result = egcd(b % a, a);
            int g = result[0];
            int y = result[1];
            int x = result[2];
            return new int[]{g, x - (b / a) * y, y};
        }
    }

    private static int modinv(int a, int m) {
        int[] result = egcd(a, m);
        if (result[0] != 1)
            throw new RuntimeException("modular inverse does not exist");
        else
            return (result[1] % m + m) % m;
    }

    private static int choose(int n, int k, int p) {
        if (k == 0)
            return 1;
        BigInteger x = BigInteger.valueOf(n);
        for (int y = n - 1; y > n - k; y--)
            x = x.multiply(BigInteger.valueOf(y)).mod(BigInteger.valueOf(p));
        BigInteger d = BigInteger.ONE;
        for (int i = 2; i <= k; i++)
            d = d.multiply(BigInteger.valueOf(i)).mod(BigInteger.valueOf(p));
        return x.multiply(BigInteger.valueOf(modinv(d.intValue(), p))).mod(BigInteger.valueOf(p)).intValue();
    }

    private static long modPow(long base, int exp, int mod) {
        if (exp == 0)
            return 1;
        long half = modPow(base, exp / 2, mod);
        long result = (half * half) % mod;
        if (exp % 2 != 0)
            result = (result * base) % mod;
        return result;
    }
}

import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int n = Integer.parseInt(scanner.nextLine());
        List<int[]> p = new ArrayList<>();
        for (int i = 0; i < n; i++) {
            String[] input = scanner.nextLine().split(" ");
            p.add(new int[]{Integer.parseInt(input[0]), Integer.parseInt(input[1])});
        }

        int ans = 0;
        int cnt = 0;
        int[][] r = new int[n][n];
        int[] q = new int[n];

        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (gcd(Math.abs(p.get(i)[0] - p.get(j)[0]), Math.abs(p.get(i)[1] - p.get(j)[1])) % 4 == 0) {
                    cnt++;
                    r[i][j] = 1;
                    q[i]++;
                    ans += n - 2;
                }
            }
        }

        for (int i = 0; i < n; i++) {
            for (int j = 1; j < n; j++) {
                if (r[i][j] == 1) {
                    ans -= q[j] * 2;
                }
            }
        }

        System.out.println(ans);
    }

    static int gcd(int a, int b) {
        while (b != 0) {
            int temp = b;
            b = a % b;
            a = temp;
        }
        return a;
    }
}

