struct FastReader {
    reader: io::StdinLock<'static>,
    buffer: String,
    tokens: Vec<String>,
    token_index: usize,
}

impl FastReader {
    fn new() -> Self {
        let stdin = io::stdin();
        FastReader {
            reader: stdin.lock(),
            buffer: String::new(),
            tokens: Vec::new(),
            token_index: 0,
        }
    }

    fn read_next_line_tokens(&mut self) {
        self.buffer.clear();
        self.reader.read_line(&mut self.buffer).unwrap();
        self.tokens = self
            .buffer
            .split_whitespace()
            .map(|s| s.to_string())
            .collect();
        self.token_index = 0;
    }

    fn next(&mut self) -> String {
        if self.token_index >= self.tokens.len() {
            self.read_next_line_tokens();
        }
        let token = self.tokens[self.token_index].clone();
        self.token_index += 1;
        token
    }

    fn next_int(&mut self) -> i32 {
        self.next().parse().unwrap()
    }

    fn reverse(arr: &mut [i32], r: usize) {
        for i in 0..=r / 2 {
            arr.swap(i, r - i);
        }
    }
}

