struct FastIO {
    input_stream: io::Stdin,
    output_stream: io::Stdout,
    buffer: [u8; 8192],
    buffer_size: usize,
    buffer_index: usize,
}

impl FastIO {
    fn new() -> Self {
        FastIO {
            input_stream: io::stdin(),
            output_stream: io::stdout(),
            buffer: [0; 8192],
            buffer_size: 0,
            buffer_index: 0,
        }
    }

    fn read_line(&mut self) -> String {
        let mut result = Vec::new();
        loop {
            if self.buffer_index >= self.buffer_size {
                self.buffer_size = self.input_stream.read(&mut self.buffer).unwrap();
                self.buffer_index = 0;
            }
            if self.buffer_size == 0 {
                break;
            }

            if let Some(newline_index) = self.buffer[self.buffer_index..self.buffer_size]
                .iter()
                .position(|&b| b == b'\n')
            {
                result.extend_from_slice(&self.buffer[self.buffer_index..self.buffer_index + newline_index]);
                self.buffer_index += newline_index + 1;
                break;
            } else {
                result.extend_from_slice(&self.buffer[self.buffer_index..self.buffer_size]);
                self.buffer_index = self.buffer_size;
            }
        }
        String::from_utf8(result).unwrap().trim_end_matches(|c| c == '\r' || c == '\n').to_string()
    }

    fn write_line(&mut self, value: i64) {
        writeln!(self.output_stream, "{}", value).unwrap();
    }
}

