const MOD: i32 = 998244353;

fn egcd(a: i32, b: i32) -> (i32, i32, i32) {
    if a == 0 {
        (b, 0, 1)
    } else {
        let (g, y, x) = egcd(b % a, a);
        (g, x - (b / a) * y, y)
    }
}

fn modinv(a: i32, m: i32) -> i32 {
    let (g, x, _) = egcd(a, m);
    if g != 1 {
        panic!("modular inverse does not exist");
    } else {
        (x % m + m) % m
    }
}

fn choose(n: i32, k: i32, p: i32) -> i32 {
    if k == 0 {
        return 1;
    }
    let mut x = n as u64;
    for y in (n - k + 1)..=n {
        x = (x * y as u64) % p as u64;
    }
    let mut d = 1u64;
    for i in 2..=k {
        d = (d * i as u64) % p as u64;
    }
    ((x * modinv(d as i32, p) as u64) % p as u64) as i32
}

