        for j in (i + 1)..n {
            if gcd((p[i as usize].0 - p[j as usize].0).abs(), (p[i as usize].1 - p[j as usize].1).abs()) % 4 == 0 {
                cnt += 1;
                r[i as usize][j as usize] = 1;
                q[i as usize] += 1;
                ans += n - 2;
            }
        }
    }

    for i in 0..n {
        for j in 1..n {
            if r[i as usize][j as usize] == 1 {
                ans -= q[j as usize] * 2;
            }
        }
    }

    println!("{}", ans);
}

fn gcd(mut a: i32, mut b: i32) -> i32 {
    while b != 0 {
        let temp = b;
        b = a % b;
        a = temp;
    }
    a
}

