class FastReader {
private:
    std::istream& _is;
    std::vector<std::string> _currentLineTokens;
    size_t _tokenIndex;

public:
    FastReader(std::istream& is = std::cin) : _is(is), _tokenIndex(0) {}

private:
    void ReadNextLineTokens() {
        std::string line;
        if (std::getline(_is, line)) {
            std::istringstream iss(line);
            _currentLineTokens.clear();
            std::string token;
            while (iss >> token) {
                _currentLineTokens.push_back(token);
            }
        } else {
            _currentLineTokens.clear();
        }
        _tokenIndex = 0;
    }

public:
    std::string Next() {
        if (_tokenIndex >= _currentLineTokens.size()) {
            ReadNextLineTokens();
        }
        return _currentLineTokens[_tokenIndex++];
    }

    int NextInt() {
        return std::stoi(Next());
    }

    long NextLong() {
        return std::stol(Next());
    }

    double NextDouble() {
        return std::stod(Next());
    }

    std::string NextLine() {
        if (_tokenIndex >= _currentLineTokens.size()) {
            ReadNextLineTokens();
        }
        std::string result = _currentLineTokens[_tokenIndex];
        for (size_t i = _tokenIndex + 1; i < _currentLineTokens.size(); ++i) {
            result += " " + _currentLineTokens[i];
        }
        _tokenIndex = _currentLineTokens.size();
        return result;
    }
};

void Reverse(std::vector<int>& a, int r) {
    for (int i = 0; i <= r / 2; ++i) {
        std::swap(a[i], a[r - i]);
    }
}

