            string line;
            getline(cin, line);
            for (int j = 0; j < m; ++j) {
                char ch = line[j];
                if (ch == 'R') d[i][j] = -1;
                else if (ch == 'U') d[i][j] = -2;
                else if (ch == 'L') d[i][j] = -3;
                else d[i][j] = -4; // Corrected back to -4 for 'D'
            }
        }

        int r = 0;
        pair<int, int> pos(0, 0);

        for (int i = 0; i < n; ++i) {
            for (int j = 0; j < m; ++j) {
                int a = i, b = j, p = d[i][j], c = 0;
                vector<pair<int, int>> st;

                while (p < 0) {
                    d[a][b] = 0;
                    st.emplace_back(a, b);
                    if (p == -1) ++b;
                    else if (p == -2) --a;
                    else if (p == -3) --b;
                    else ++a; // Corrected back to ++a for 'D'
                    ++c;
                    if (a >= 0 && a < n && b >= 0 && b < m)
                        p = d[a][b];
                    else {
                        for (int ii = 0; ii < st.size(); ++ii) {
                            auto tuple = st[ii];
                            d[tuple.first][tuple.second] = c - ii;
                        }
                        p = -1;
