class Dsu {
public:
    std::vector<int> parent;

    Dsu(int n) : parent(n + 1) {}

    void MakeSet() {
        for (int i = 1; i <= parent.size() - 1; ++i) {
            parent[i] = i;
        }
    }

    int FindParent(int node) {
        if (node == parent[node])
            return node;

        parent[node] = FindParent(parent[node]);
        return parent[node];
    }

    int Union(int u, int v) {
        int u_parent = FindParent(u);
        int v_parent = FindParent(v);

        if (u_parent != v_parent) {
            parent[v_parent] = u_parent;
            return 0;
        } else {
            return -1;
        }
    }

    void CheckComponent(int u, int v) {
        if (FindParent(u) != FindParent(v))
            std::cout << "Both belongs to different components" << std::endl;
        else
            std::cout << "same component" << std::endl;
