        std::string line = fastIO.ReadLine();
        std::istringstream iss(line);
        std::vector<int> arr(n);
        for (int i = 0; i < n; ++i) {
            iss >> arr[i];
        }
        if (n == 2) {
            fastIO.WriteLine(static_cast<long>(arr[0]) * arr[1]);
        } else {
            long res = -1;
            for (int i = 0; i < n - 1; ++i) {
                long product = static_cast<long>(std::max(arr[i + 1], arr[i])) * std::min(arr[i + 1], arr[i]);
                if (product > res) {
                    res = product;
                }
            }
            fastIO.WriteLine(res);
        }
    }
    return 0;
}

