const int Mod = 998244353;

std::tuple<int, int, int> Egcd(int a, int b) {
    if (a == 0)
        return {b, 0, 1};
    else {
        auto [g, y, x] = Egcd(b % a, a);
        return {g, x - (b / a) * y, y};
    }
}

int Modinv(int a, int m) {
    auto [g, x, _] = Egcd(a, m);
    if (g != 1)
        throw std::runtime_error("modular inverse does not exist");
    else
        return (x % m + m) % m;
}

int Choose(int n, int k, int p) {
    if (k == 0)
        return 1;
    long long x = n;
    for (int y = n - 1; y > n - k; y--)
        x = (x * y) % p;
    long long d = 1;
    for (int i = 2; i <= k; i++)
        d = (d * i) % p;
    return static_cast<int>((x * Modinv(static_cast<int>(d), p)) % p);
}

void Solve() {
    int n;
    std::cin >> n;
    bool wb_poss = n > 1;
    bool bw_poss = n > 1;
    int w = 0;
    int b = 0;
    int q = 0;
    int free = 0;
    bool any_bad_poss = n > 1;

    for (int i = 0; i < n; i++) {
        std::string s;
        std::cin >> s;
        if (s[0] == 'B') {
            b++;
            wb_poss = false;
        } else if (s[0] == 'W') {
            w++;
            bw_poss = false;
        } else if (s[0] == '?') {
            q++;
        }

        if (s[1] == 'B') {
            b++;
            bw_poss = false;
        } else if (s[1] == 'W') {
            w++;
            wb_poss = false;
        } else if (s[1] == '?') {
            q++;
        }

        if (s == "??") {
            free++;
        } else if (s[0] == s[1]) {
            any_bad_poss = false;
        }
    }

    int w_needed = n - w;
    if (w_needed > q || w_needed < 0) {
        std::cout << 0 << std::endl;
        return;
    }

    int num_bad_poss;
    if (any_bad_poss) {
        long long bad_possibilities = std::pow(2, free);
        if (bw_poss)
            bad_possibilities -= 1;
        if (wb_poss)
            bad_possibilities -= 1;
        num_bad_poss = static_cast<int>(bad_possibilities % Mod);
    } else {
        num_bad_poss = 0;
    }

    std::cout << (Choose(q, w_needed, Mod) - num_bad_poss + Mod) % Mod << std::endl;
}

