class FastReader {
    private var sr = StreamReader()
    private var currentLineTokens: [String]
    private var tokenIndex: Int

    init() {
        currentLineTokens = []
        tokenIndex = 0
    }

    private func readNextLineTokens() {
        currentLineTokens = sr.readLine()?.split(separator: " ").map { String($0) } ?? []
        tokenIndex = 0
    }

    func next() -> String {
        if tokenIndex >= currentLineTokens.count {
            readNextLineTokens()
        }
        return currentLineTokens[tokenIndex]
    }

    func nextInt() -> Int {
        return Int(next())!
    }

    func nextLong() -> Int64 {
        return Int64(next())!
    }

    func nextDouble() -> Double {
        return Double(next())!
    }

    func nextLine() -> String {
        if tokenIndex >= currentLineTokens.count {
            readNextLineTokens()
        }
        let result = currentLineTokens[tokenIndex...].joined(separator: " ")
        tokenIndex = currentLineTokens.count
        return result
    }
}

class StreamReader {
    private var buffer: [Character] = []
    private let reader = FileHandle.standardInput

    func readLine() -> String? {
        while !buffer.contains(where: { $0 == "\n" }) {
            if let data = reader.availableData, let string = String(data: data, encoding: .utf8) {
                buffer.append(contentsOf: string)
            } else {
                return nil
            }
        }

        guard let endIndex = buffer.firstIndex(of: "\n") else { return nil }
        let line = String(buffer.prefix(upTo: endIndex))
        buffer.removeFirst(endIndex + 1)
        return line
    }
}

func reverse(_ a: inout [Int], _ r: Int) {
    for i in 0...r / 2 {
        let l = i, h = r - i
        let t = a[l]
        a[l] = a[h]
        a[h] = t
    }
}

