class FastIO {
    private let inputStream: InputStream
    private let readBuffer = UnsafeMutablePointer<UInt8>.allocate(capacity: 8192)

    init(inputStream: InputStream) {
        self.inputStream = inputStream
        inputStream.open()
    }

    deinit {
        inputStream.close()
        readBuffer.deallocate()
    }

    func readToEnd() -> String? {
        var buffer = Data()
        while true {
            let bytesRead = inputStream.read(into: readBuffer, maxLength: 8192)
            if bytesRead == -1 { break } // End of stream
            if bytesRead > 0 {
                buffer.append(readBuffer, count: bytesRead)
            }
        }
        return String(data: buffer, encoding: .ascii)
    }

    func readLine() -> String? {
        var line = ""
        while let character = inputStream.read(into: readBuffer, maxLength: 1)?.first?.asciiValue {
            if character == UInt8(ascii: "\n") || character == UInt8(ascii: "\r") { break } // Handle newline and carriage return
            line.append(Character(UnicodeScalar(character)))
        }
        return line.isEmpty ? nil : line
    }
}

