import Foundation

class FastIO {
    private let bufferSize: Int = 8192
    private var inputStream: InputStream
    private var outputStream: OutputStream
    private var buffer: [UInt8] = Array(repeating: 0, count: bufferSize)
    private var bufferSize: Int = 0
    private var bufferIndex: Int = 0

    init(inputStream: InputStream, outputStream: OutputStream) {
        self.inputStream = inputStream
        self.outputStream = outputStream
        inputStream.open()
        outputStream.open()
    }

    func readLine() -> String? {
        let ms = NSMutableData()
        while true {
            if bufferIndex >= bufferSize {
                bufferSize = inputStream.read(&buffer, maxLength: bufferSize)
                bufferIndex = 0
            }
            if bufferSize == 0 { break }

            if let newlineIndex = (buffer[bufferIndex..<bufferSize] as ContiguousArray).firstIndex(of: UInt8(ascii: "\n")) {
                ms.append(buffer[bufferIndex...newlineIndex])
                bufferIndex = newlineIndex + 1
                break
            } else {
                ms.append(buffer[bufferIndex..<bufferSize])
                bufferIndex = bufferSize
            }
        }
        return String(data: ms as Data, encoding: .ascii)?.trimmingCharacters(in: .whitespacesAndNewlines)
    }

    func writeLine(_ value: Int64) {
        let data = "\(value)\n".data(using: .ascii)!
        _ = outputStream.write((data as NSData).bytes.bindMemory(to: UInt8.self, capacity: data.count), maxLength: data.count)
    }
}

func main() {
    if let inputStream = InputStream(fileAtPath: "/dev/stdin"), let outputStream = OutputStream(toFileAtPath: "/dev/stdout", append: false) {
        let fastIO = FastIO(inputStream: inputStream, outputStream: outputStream)
        if let tString = fastIO.readLine(), let t = Int(tString) {
            for _ in 0..<t {
                if let nString = fastIO.readLine(), let n = Int(nString) {
                    if let inputLine = fastIO.readLine() {
                        let inputArray = inputLine.split(separator: " ")
                        var arr: [Int] = []
                        for item in inputArray {
                            if let num = Int(item) {
                                arr.append(num)
                            }
                        }
                        if n == 2 {
                            fastIO.writeLine(Int64(arr[0]) * Int64(arr[1]))
                        } else {
                            var res: Int64 = -1
                            for i in 0..<n-1 {
                                let product: Int64 = Int64(max(arr[i], arr[i+1])) * Int64(min(arr[i], arr[i+1]))
                                if product > res {
                                    res = product
                                }
                            }
                            fastIO.writeLine(res)
                        }
                    }
                }
            }
        }
    }
}

