BUFSIZE = 8192

class FastIO:
    def __init__(self):
        self.buffer = bytearray(BUFSIZE)
        self.pos = 0
        self.end = 0

    def read(self):
        while True:
            n = sys.stdin.readinto(self.buffer[self.end:])
            if n == 0:
                break
            self.end += n

    def readline(self):
        result = []
        while not self.is_empty() or self.read():
            while self.pos < self.end and self.buffer[self.pos] != b'\n':
                result.append(chr(self.buffer[self.pos]))
                self.pos += 1
            if self.pos < self.end:
                # Skip the newline character
                self.pos += 1
                break
        return ''.join(result)

    def is_empty(self):
        return self.pos == self.end

