            lines.shift(); // Skip the empty line
            const nm = lines.shift()!.split(/\s+/).map(Number);
            const n = nm[0];
            const m = nm[1];

            let d: number[][] = Array.from({ length: n }, () => Array(m).fill(-1));
            for (let i = 0; i < n; i++) {
                const line = lines.shift()!.trim();
                for (let j = 0; j < m; j++) {
                    const c = line[j];
                    d[i][j] = matchChar(c);
                }
            }

            let r = 0;
            let pos: [number, number] = [0, 0];

            for (let i = 0; i < n; i++) {
                for (let j = 0; j < m; j++) {
                    let [a, b] = [i, j];
                    let p = d[i][j];
                    let c = 0;
                    const st: [number, number][] = [];

                    while (p < 0) {
                        d[a][b] = 0;
                        st.push([a, b]);
                        if (p === -1) b += 1;
                        else if (p === -2) a -= 1;
                        else if (p === -3) b -= 1;
                        else a += 1;
                        c += 1;
                        if (a >= 0 && a < n && b >= 0 && b < m) {
                            p = d[a][b];
                        } else {
                            for (let ii = 0; ii < st.length; ii++) {
                                const [x, y] = st[ii];
                                d[x][y] = c - ii;
                            }
                            p = -1;
