                        let flag = false;
                        for (let ii = 0; ii < st.length; ii++) {
                            const [x, y] = st[ii];
                            d[x][y] = flag ? c - jj : c - ii;
                            if (x === a && y === b) { flag = true; jj = ii; }
                        }
                    }

                    if (p > 0) {
                        for (let ii = 0; ii < st.length; ii++) {
                            const [x, y] = st[ii];
                            d[x][y] = p + c - ii;
                        }
                    }

                    if (d[i][j] > r) {
                        r = d[i][j];
                        pos = [i, j];
                    }
                }
