    let black = 0;
    let white = 0;
    let full = false;

    for (let i = 0; i < n; i++) {
        const line = lines[i + 1];
        ls.push(line);
        if (line.charAt(0) === 'W') {
            white += 1;
        }
        if (line.charAt(0) === 'B') {
            black += 1;
        }
        if (line.charAt(1) === 'W') {
            white += 1;
        }
        if (line.charAt(1) === 'B') {
            black += 1;
        }
        if (line.charAt(0) !== '?' && line.charAt(0) === line.charAt(1)) {
            full = true;
        }
    }

    if (black > n || white > n) {
        stdout.write('0\n');
        return;
    }

    const fact: number[] = new Array(2 * n + 1).fill(0);
    const invFact: number[] = new Array(2 * n + 1).fill(0);
    fact[0] = 1;
    invFact[0] = 1;

    for (let i = 1; i <= 2 * n; i++) {
        fact[i] = mul(fact[i - 1], i);
        invFact[i] = modInverse(fact[i]);
    }

    const empty = 2 * n - black - white;
    let ans = nCr(empty, n - black, fact, invFact);

    if (full) {
        stdout.write(`${ans}\n`);
        return;
    }

    let invalid = 1;
    let wb = true;
    let bw = true;

    for (const line of ls) {
