        if (line.charAt(0) === 'W' || line.charAt(1) === 'B') {
            bw = false;
        }
    }

    if (wb) {
        invalid -= 1;
    }
    if (bw) {
        invalid -= 1;
    }

    ans = (ans - invalid + MOD) % MOD; // Ensure non-negative result
    stdout.write(`${ans}\n`);
}

