                stdin.read(this.buffer.subarray(this.end), 0, BUFSIZE - this.end, null, (err, bytesRead) => {
                    if (err) {
                        reject(err);
                    } else {
                        resolve(bytesRead || 0);
                    }
                });
            });
            if (n === 0) {
                break;
            }
            this.end += n;
        }
    }

    async readline(): Promise<string> {
        let result = '';
        while (!this.isEmpty() || await this.read()) {
            while (this.pos < this.end && this.buffer[this.pos] !== 10) { // ASCII for '\n'
                result += String.fromCharCode(this.buffer[this.pos]);
                this.pos += 1;
            }
            if (this.pos < this.end) {
                // Skip the newline character
                this.pos += 1;
                break;
            }
        }
        return result;
    }

    isEmpty(): boolean {
        return this.pos === this.end;
    }
}

