        if (!n) {
            n = parseInt(line.trim(), 10);
        } else {
            const coords = line.trim().split(/\s+/).map(Number);
            p.push([coords[0], coords[1]]);
            if (p.length === n) {
                rl.close();
                process.stdout.write(`${calculateAnswer(n, p)}\n`);
            }
        }
    });
}

function calculateAnswer(n: number, p: [number, number][]): number {
    let ans = 0;
    let cnt = 0;
    const r: number[][] = Array.from({ length: n }, () => Array(n).fill(0));
    const q: number[] = new Array(n).fill(0);

    for (let i = 0; i < n; i++) {
        for (let j = i + 1; j < n; j++) {
            const dx = Math.abs(p[i][0] - p[j][0]);
            const dy = Math.abs(p[i][1] - p[j][1]);
            if (gcd(dx, dy) % 4 === 0) {
                cnt += 1;
                r[i][j] = 1;
                q[i] += 1;
                ans += n - 2;
            }
        }
    }

    for (let i = 0; i < n; i++) {
        for (let j = 1; j < n; j++) {
            if (r[i][j] === 1) {
                ans -= q[j] * 2;
            }
        }
    }

    return ans;
}

function gcd(a: number, b: number): number {
    while (b !== 0) {
        const t = b;
        b = a % b;
        a = t;
    }
    return a;
}

