		for i := range d {
			d[i] = make([]int, m)
			for j := range d[i] {
				d[i][j] = -1
			}
		}

		for i := 0; i < n; i++ {
			scanner.Scan()
			line := strings.TrimSpace(scanner.Text())
			for j, c := range line {
				switch c {
				case 'R':
					d[i][j] = -1
				case 'U':
					d[i][j] = -2
				case 'L':
					d[i][j] = -3
				default:
					d[i][j] = -4
				}
			}
		}

		var r int
		pos := struct{ x, y int }{0, 0}

		for i := 0; i < n; i++ {
			for j := 0; j < m; j++ {
				a, b := i, j
				p := d[i][j]
				c := 0
				var st []struct{ x, y int }

				for p < 0 {
					d[a][b] = 0
					st = append(st, struct{ x, y int }{a, b})
					switch p {
					case -1:
						b++
					case -2:
						a--
					case -3:
						b--
					default:
						a++
					}
					c++
					if a >= 0 && b >= 0 && a < n && b < m {
						p = d[a][b]
					} else {
						for ii, coord := range st {
							d[coord.x][coord.y] = c - ii
						}
						p = -1
						break
					}
				}

				if p == 0 {
					flag := false
					jj := 0
					for ii, coord := range st {
						if flag {
							d[coord.x][coord.y] = c - jj
						} else {
							d[coord.x][coord.y] = c - ii
						}
						if coord.x == a && coord.y == b {
							flag = true
							jj = ii
						}
					}
				}

				if p > 0 {
					for ii, coord := range st {
						d[coord.x][coord.y] = p + c - ii
					}
				}

				if d[i][j] > r {
					r = d[i][j]
					pos = struct{ x, y int }{i, j}
				}
			}
		}

		fmt.Printf("%d %d %d\n", pos.x+1, pos.y+1, r)
	}
