const BUFSIZE = 8192

type FastIO struct {
	buffer []byte
	pos    int
	end    int
}

func NewFastIO() *FastIO {
	return &FastIO{
		buffer: make([]byte, BUFSIZE),
		pos:    0,
		end:    0,
	}
}

func (f *FastIO) read() error {
	for {
		n, err := os.Stdin.Read(f.buffer[f.end:])
		if err != nil && n == 0 {
			return err
		}
		f.end += n
		if n < BUFSIZE {
			break
		}
	}
	return nil
}

func (f *FastIO) readline() (string, error) {
	var result strings.Builder
	for !f.isEmpty() || f.read() == nil {
		for f.pos < f.end && f.buffer[f.pos] != '\n' {
			result.WriteByte(f.buffer[f.pos])
			f.pos++
		}
		if f.pos < f.end {
			// Skip the newline character
			f.pos++
			break
		}
	}
	return result.String(), nil
}

func (f *FastIO) isEmpty() bool {
	return f.pos == f.end
}

