func main() {
	scanner := bufio.NewScanner(os.Stdin)
	var n int
	if scanner.Scan() {
		n, _ = strconv.Atoi(strings.TrimSpace(scanner.Text()))
	}

	p := make([][2]int, n)
	for i := 0; i < n; i++ {
		if scanner.Scan() {
			line := strings.TrimSpace(scanner.Text())
			coords := strings.Fields(line)
			x, _ := strconv.Atoi(coords[0])
			y, _ := strconv.Atoi(coords[1])
			p[i] = [2]int{x, y}
		}
	}

	var ans int
	cnt := 0
	r := make([][]int, n)
	for i := range r {
		r[i] = make([]int, n)
	}
	q := make([]int, n)

	for i := 0; i < n; i++ {
		for j := i + 1; j < n; j++ {
			dx := abs(p[i][0] - p[j][0])
			dy := abs(p[i][1] - p[j][1])
			if gcd(dx, dy)%4 == 0 {
				cnt++
				r[i][j] = 1
				q[i]++
				ans += n - 2
			}
		}
	}

	for i := 0; i < n; i++ {
		for j := 1; j < n; j++ {
			if r[i][j] == 1 {
				ans -= q[j] * 2
			}
		}
	}

	fmt.Println(ans)
}

func gcd(a, b int) int {
	for b != 0 {
		t := b
		b = a % b
		a = t
	}
	return a
}

func abs(x int) int {
	if x < 0 {
		return -x
	}
	return x
}

