public class Main {

    public static List<Integer> nextLargerElement(int[] arr, int n, boolean f) {
        List<Integer> s = new ArrayList<>();
        List<Integer> ans = new ArrayList<>(List.of(new Integer[n]));
        for (int i = 0; i < n; i++) {
            ans.set(i, -1);
        }
        for (int i = 0; i < n; i++) {
            while (!s.isEmpty() && arr[s.get(s.size() - 1)] < arr[i]) {
                s.remove(s.size() - 1);
            }
            if (!s.isEmpty()) {
                ans.set(i, s.get(s.size() - 1));
            }
            s.add(i);
        }
        if (f) {
            for (int i = 0; i < n; i++) {
                if (ans.get(i) != -1) {
                    ans.set(i, (n - 1) - ans.get(i));
                }
            }
        }
        return ans;
    }

    public static int dfs(int i, List<List<Integer>> adj, Integer p, int ans) {
        boolean f = true;
        int a1 = 0;
        for (int j : adj.get(i)) {
            if (!p.equals(j)) {
                a1 += dfs(j, adj, i, ans + 1);
                f = false;
            }
        }
        if (f) {
            a1 += ans * (ans - 1) / 2;
        }
        return a1;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int t = Integer.parseInt(br.readLine());

        for (int i = 0; i < t; i++) {
            String line = br.readLine();
            String[] parts = line.split("\\s+");
            int n = Integer.parseInt(parts[0]);
            int s = Integer.parseInt(parts[1]);
            System.out.println(s / ((n + 2) / 2));
        }
    }
}

