public class Main {
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int t = Integer.parseInt(reader.readLine().trim());

        for (int testCase = 0; testCase < t; testCase++) {
            reader.readLine(); // Skip the empty line
            String[] nm = reader.readLine().trim().split("\\s+");
            int n = Integer.parseInt(nm[0]);
            int m = Integer.parseInt(nm[1]);

            int[][] d = new int[n][m];
            for (int i = 0; i < n; i++) {
                String line = reader.readLine().trim();
                for (int j = 0; j < m; j++) {
                    char c = line.charAt(j);
                    switch (c) {
                        case 'R':
                            d[i][j] = -1;
                            break;
                        case 'U':
                            d[i][j] = -2;
                            break;
                        case 'L':
                            d[i][j] = -3;
                            break;
                        default:
                            d[i][j] = -4;
                    }
                }
            }

            int r = 0;
            int[] pos = {0, 0};

            for (int i = 0; i < n; i++) {
                for (int j = 0; j < m; j++) {
                    int a = i;
                    int b = j;
                    int p = d[i][j];
                    int c = 0;
                    List<int[]> st = new ArrayList<>();

                    while (p < 0) {
                        d[a][b] = 0;
                        st.add(new int[]{a, b});
                        if (p == -1) b++;
                        else if (p == -2) a--;
                        else if (p == -3) b--;
                        else a++;
                        c++;
                        if (a >= 0 && b >= 0 && a < n && b < m) {
                            p = d[a][b];
                        } else {
                            for (int ii = 0; ii < st.size(); ii++) {
                                int[] coord = st.get(ii);
                                d[coord[0]][coord[1]] = c - ii;
                            }
                            p = -1;
                            break;
                        }
                    }

                    if (p == 0) {
                        boolean flag = false;
                        for (int ii = 0; ii < st.size(); ii++) {
                            int[] coord = st.get(ii);
                            d[coord[0]][coord[1]] = flag ? c - ii : c - ii;
                            if (coord[0] == a && coord[1] == b) {
                                flag = true;
                            }
                        }
                    }

                    if (p > 0) {
                        for (int ii = 0; ii < st.size(); ii++) {
                            int[] coord = st.get(ii);
                            d[coord[0]][coord[1]] = p + c - ii;
                        }
                    }

                    if (d[i][j] > r) {
                        r = d[i][j];
                        pos[0] = i;
                        pos[1] = j;
                    }
                }
            }

            System.out.println((pos[0] + 1) + " " + (pos[1] + 1) + " " + r);
        }
    }
}

