import java.io.*;
import java.util.*;

public class Main {
    private static final int MOD = 1_000_000_007;
    private static final int INF = (int) (1L << 60);

    static class Dsu {
        int[] parent;

        Dsu(int n) {
            parent = new int[n + 1];
            for (int i = 1; i <= n; i++) {
                parent[i] = i;
            }
        }

        int findParent(int node) {
            if (node == parent[node]) {
                return node;
            }
            parent[node] = findParent(parent[node]);
            return parent[node];
        }

        int union(int u, int v) {
            int uParent = findParent(u);
            int vParent = findParent(v);

            if (uParent != vParent) {
                parent[vParent] = uParent;
                return 0;
            } else {
                return -1;
            }
        }

        void checkComponent(int u, int v) {
            if (findParent(u) != findParent(v)) {
                System.out.println("Both belongs to different components");
            } else {
                System.out.println("same component");
            }
        }
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        String[] firstLine = br.readLine().split("\\s+");
        int n = Integer.parseInt(firstLine[0]);
        int m1 = Integer.parseInt(firstLine[1]);
        int m2 = Integer.parseInt(firstLine[2]);

        Dsu d1 = new Dsu(n);
        Dsu d2 = new Dsu(n);

        int flag = 0;
        for (int i = 0; i < m1; i++) {
            String[] line = br.readLine().split("\\s+");
            int u = Integer.parseInt(line[0]);
            int v = Integer.parseInt(line[1]);
            if (d1.union(u, v) == -1) {
                flag = 1;
            }
        }

        for (int i = 0; i < m2; i++) {
            String[] line = br.readLine().split("\\s+");
            int u = Integer.parseInt(line[0]);
            int v = Integer.parseInt(line[1]);
            if (d2.union(u, v) == -1) {
                flag = 1;
            }
        }

        if (flag != 0) {
            System.out.println("0");
            return;
        }

        List<int[]> v = new ArrayList<>();
        for (int i = 1; i <= n; i++) {
            for (int j = i + 1; j <= n; j++) {
                int y = d1.findParent(j);
                int y1 = d1.findParent(y);
                int x = d2.findParent(j);
                int x1 = d2.findParent(x);

                if (d1.union(i, j) == -1) {
                    d1.parent[y] = y1;
                } else if (d2.union(i, j) == -1) {
                    d2.parent[x] = x1;
                    d1.parent[y] = y1;
                } else {
                    d1.union(i, j);
                    d2.union(i, j);
                    v.add(new int[]{i, j});
                }
            }
        }

        System.out.println(v.size());
        for (int[] pair : v) {
            System.out.println(pair[0] + " " + pair[1]);
        }
    }
}

