import java.io.*;
import java.util.*;

public class Main {

    private static final long MOD = 998244353;

    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        int n = Integer.parseInt(reader.readLine());

        List<String> ls = new ArrayList<>();
        int black = 0;
        int white = 0;
        boolean full = false;

        for (int i = 0; i < n; i++) {
            String line = reader.readLine();
            ls.add(line);
            if (line.charAt(0) == 'W') {
                white++;
            }
            if (line.charAt(0) == 'B') {
                black++;
            }
            if (line.charAt(1) == 'W') {
                white++;
            }
            if (line.charAt(1) == 'B') {
                black++;
            }
            if (line.charAt(0) != '?' && line.charAt(0) == line.charAt(1)) {
                full = true;
            }
        }

        if (black > n || white > n) {
            System.out.println("0");
            return;
        }

        long[] fact = new long[2 * n + 1];
        long[] invFact = new long[2 * n + 1];
        fact[0] = 1;
        invFact[0] = 1;

        for (int i = 1; i <= 2 * n; i++) {
            fact[i] = mul(fact[i - 1], i);
            invFact[i] = modInverse(fact[i]);
        }

        int empty = 2 * n - black - white;
        long ans = nCr(empty, n - black, fact, invFact);

        if (full) {
            System.out.println(ans);
            return;
        }

        long invalid = 1;
        boolean wb = true;
        boolean bw = true;

        for (String line : ls) {
            if (line.charAt(0) == '?' && line.charAt(1) == '?') {
                invalid = mul(invalid, 2);
            }
            if (line.charAt(0) == 'B' || line.charAt(1) == 'W') {
                wb = false;
            }
            if (line.charAt(0) == 'W' || line.charAt(1) == 'B') {
                bw = false;
            }
        }

        if (wb) {
            invalid -= 1;
        }
        if (bw) {
            invalid -= 1;
        }

        ans -= invalid;
        System.out.println(ans);
    }

    private static long binPow(long a, long b) {
        long res = 1;
        while (b > 0) {
            a %= MOD;
            if ((b & 1) == 1) {
                res = mul(res, a);
            }
            b >>= 1;
            a = mul(a, a);
        }
        return res;
    }

    private static long modInverse(long a) {
        return binPow(a, MOD - 2);
    }

    private static long mul(long a, long b) {
        return (a * b) % MOD;
    }

    private static long nCr(int n, int r, long[] fact, long[] invFact) {
        long res = mul(fact[n], invFact[r]);
        res = mul(res, invFact[n - r]);
        return res;
    }
}

import java.io.BufferedReader;
