public class Main {
    private static final int BUFSIZE = 8192;

    static class FastIO {
        private byte[] buffer;
        private int pos, end;

        public FastIO() {
            this.buffer = new byte[BUFSIZE];
            this.pos = 0;
            this.end = 0;
        }

        public void read() throws IOException {
            while (true) {
                int n = System.in.read(buffer, end, BUFSIZE - end);
                if (n == -1 || n == 0) break;
                end += n;
            }
        }

        public String readline() throws IOException {
            StringBuilder result = new StringBuilder();
            while (!isEmpty()) {
                while (pos < end && buffer[pos] != '\n') {
                    result.append((char) buffer[pos]);
                    pos++;
                }
                if (pos < end) {
                    // Skip the newline character
                    pos++;
                    break;
                }
            }
            return result.toString();
        }

        public boolean isEmpty() {
            return pos == end;
        }
    }

    static void print(String[] args, String sep, String end) {
        PrintWriter stdout = new PrintWriter(new OutputStreamWriter(System.out));
        for (int i = 0; i < args.length; i++) {
            if (i > 0) {
                stdout.print(sep);
            }
            stdout.print(args[i]);
        }
        stdout.println(end);
        stdout.flush();
    }

    static int inp() throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
