using System;
using System.Collections.Generic;
using System.IO;

class Program
{
    static List<int> NextLargerElement(int[] arr, int n, bool f)
    {
        var s = new Stack<int>();
        var ans = new int[n];
        for (int i = 0; i < n; i++)
        {
            while (s.Count > 0 && arr[s.Peek()] < arr[i])
            {
                s.Pop();
            }
            if (s.Count > 0)
            {
                ans[i] = s.Peek();
            }
            s.Push(i);
        }
        if (f)
        {
            for (int i = 0; i < n; i++)
            {
                if (ans[i] != -1)
                {
                    ans[i] = (n - 1) - ans[i];
                }
            }
        }
        return new List<int>(ans);
    }

    static int Dfs(int i, List<List<int>> adj, int? p, int ans)
    {
        bool f = true;
        int a1 = 0;
        foreach (var j in adj[i])
        {
            if (j != p)
            {
                a1 += Dfs(j, adj, i, ans + 1);
                f = false;
            }
        }
        if (f)
        {
            a1 += ans * (ans - 1) / 2;
        }
        return a1;
    }

    static void Main()
    {
        using (var reader = new StreamReader(Console.OpenStandardInput()))
        {
            int t = int.Parse(reader.ReadLine());

            for (int _ = 0; _ < t; _++)
            {
                var line = reader.ReadLine();
                var parts = Array.ConvertAll(line.Split(' '), int.Parse);
                int n = parts[0];
                int s = parts[1];
                Console.WriteLine(s / ((n + 2) / 2));
            }
        }
    }
}

