                            {
                                d[a, b] = 0;
                                st.Add((a, b));
                                if (p == -1) b++;
                                else if (p == -2) a--;
                                else if (p == -3) b--;
                                else a++;
                                c++;
                                p = d[a, b];
                            }
                            else
