using System;
using System.Collections.Generic;
using System.IO;

class Program
{
    const int MOD = 1_000_000_007;
    const long INF = 1L << 60;

    class Dsu
    {
        public List<int> Parent { get; private set; }

        public Dsu(int n)
        {
            Parent = new List<int>(new int[n + 1]);
            for (int i = 1; i <= n; i++)
            {
                Parent[i] = i;
            }
        }

        public int FindParent(int node)
        {
            if (node == Parent[node])
            {
                return node;
            }
            Parent[node] = FindParent(Parent[node]);
            return Parent[node];
        }

        public int Union(int u, int v)
        {
            int uParent = FindParent(u);
            int vParent = FindParent(v);

            if (uParent != vParent)
            {
                Parent[vParent] = uParent;
                return 0;
            }
            else
            {
                return -1;
            }
        }

        public void CheckComponent(int u, int v)
        {
            if (FindParent(u) != FindParent(v))
            {
                Console.WriteLine("Both belongs to different components");
            }
            else
            {
                Console.WriteLine("same component");
            }
        }
    }

    static void Main()
    {
        using (var reader = new StreamReader(Console.OpenStandardInput()))
        using (var writer = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = true })
        {
            var firstLine = reader.ReadLine().Split();
            int n = int.Parse(firstLine[0]);
            int m1 = int.Parse(firstLine[1]);
            int m2 = int.Parse(firstLine[2]);

            Dsu d1 = new Dsu(n);
            Dsu d2 = new Dsu(n);

            int flag = 0;
            for (int i = 0; i < m1; i++)
            {
                var line = reader.ReadLine().Split();
                int u = int.Parse(line[0]);
                int v = int.Parse(line[1]);
                if (d1.Union(u, v) == -1)
                {
                    flag = 1;
                }
            }

            for (int i = 0; i < m2; i++)
            {
                var line = reader.ReadLine().Split();
                int u = int.Parse(line[0]);
                int v = int.Parse(line[1]);
                if (d2.Union(u, v) == -1)
                {
                    flag = 1;
                }
            }

            if (flag != 0)
            {
                writer.WriteLine("0");
                return;
            }

            List<(int, int)> edges = new List<(int, int)>();
            for (int i = 1; i <= n; i++)
            {
                for (int j = i + 1; j <= n; j++)
                {
                    int y = d1.FindParent(j);
                    int y1 = d1.FindParent(y);
                    int x = d2.FindParent(j);
                    int x1 = d2.FindParent(x);

                    if (d1.Union(i, j) == -1)
                    {
                        d1.Parent[y] = y1;
                    }
                    else if (d2.Union(i, j) == -1)
                    {
                        d2.Parent[x] = x1;
                        d1.Parent[y] = y1;
                    }
                    else
                    {
                        d1.Union(i, j);
                        d2.Union(i, j);
                        edges.Add((i, j));
                    }
                }
            }

            writer.WriteLine(edges.Count);
            foreach (var pair in edges)
            {
                writer.WriteLine($"{pair.Item1} {pair.Item2}");
            }
        }
    }
}

