using System;
using System.Collections.Generic;
using System.IO;

class Program
{
    const long MOD = 998244353;

    static long BinPow(long a, long b)
    {
        long res = 1;
        while (b > 0)
        {
            a %= MOD;
            if ((b & 1) == 1)
            {
                res = (res * a) % MOD;
            }
            b >>= 1;
            a = (a * a) % MOD;
        }
        return res;
    }

    static long ModInverse(long a)
    {
        return BinPow(a, MOD - 2);
    }

    static long Mul(long a, long b)
    {
        return (a * b) % MOD;
    }

    static long NCr(int n, int r, long[] fact, long[] invFact)
    {
        long res = Mul(fact[n], invFact[r]);
        res = Mul(res, invFact[n - r]);
        return res;
    }

    static void Main()
    {
        var reader = new StreamReader(Console.OpenStandardInput());
        var writer = new StreamWriter(Console.OpenStandardOutput()) { AutoFlush = true };
        int n = int.Parse(reader.ReadLine());

        List<string> ls = new List<string>(n);
        int black = 0;
        int white = 0;
        bool full = false;

        for (int i = 0; i < n; i++)
        {
            string line = reader.ReadLine();
            ls.Add(line);
            if (line[0] == 'W')
            {
                white++;
            }
            if (line[0] == 'B')
            {
                black++;
            }
            if (line[1] == 'W')
            {
                white++;
            }
            if (line[1] == 'B')
            {
                black++;
            }
            if (line[0] != '?' && line[0] == line[1])
            {
                full = true;
            }
        }

        if (black > n || white > n)
        {
            writer.WriteLine("0");
            return;
        }

        long[] fact = new long[2 * n + 1];
        long[] invFact = new long[2 * n + 1];
        fact[0] = 1;
        invFact[0] = 1;

        for (int i = 1; i <= 2 * n; i++)
        {
            fact[i] = Mul(fact[i - 1], i);
            invFact[i] = ModInverse(fact[i]);
        }

        int empty = 2 * n - black - white;
        long ans = NCr(empty, n - black, fact, invFact);

        if (full)
        {
            writer.WriteLine(ans);
            return;
        }

        long invalid = 1;
        bool wb = true;
        bool bw = true;

        foreach (var line in ls)
        {
            if (line[0] == '?' && line[1] == '?')
            {
                invalid = Mul(invalid, 2);
            }
            if (line[0] == 'B' || line[1] == 'W')
            {
                wb = false;
            }
            if (line[0] == 'W' || line[1] == 'B')
            {
                bw = false;
            }
        }

        if (wb)
        {
            invalid -= 1;
        }
        if (bw)
        {
            invalid -= 1;
        }

        ans -= invalid;
        writer.WriteLine(ans);
    }
}

using System;
