class Program
{
    const int BUFSIZE = 8192;

    class FastIO
    {
        byte[] buffer;
        int pos;
        int end;

        public FastIO()
        {
            buffer = new byte[BUFSIZE];
            pos = 0;
            end = 0;
        }

        public void Read()
        {
            while (true)
            {
                int n = Console.OpenStandardInput().Read(buffer, end, BUFSIZE - end);
                if (n == 0) break;
                end += n;
            }
        }

        public string ReadLine()
        {
            var result = new List<char>();
            while (!IsEmpty() || Read() > 0)
            {
                while (pos < end && buffer[pos] != '\n')
                {
                    result.Add((char)buffer[pos]);
                    pos++;
                }
                if (pos < end)
                {
                    // Skip the newline character
                    pos++;
                    break;
                }
            }
            return new string(result.ToArray());
        }

        public bool IsEmpty()
        {
            return pos == end;
        }
    }

    static void Print(IEnumerable<string> args, string sep, string end)
    {
        var stdout = Console.OpenStandardOutput();
        using (var writer = new System.IO.StreamWriter(stdout, System.Text.Encoding.UTF8, BUFSIZE, true))
        {
            int i = 0;
            foreach (var arg in args)
            {
                if (i > 0) writer.Write(sep);
                writer.Write(arg);
                i++;
            }
            writer.WriteLine(end);
        }
    }

