using System.Linq;

class Program
{
    static void Main()
    {
        var lines = Console.In.ReadToEnd().Split(new[] { '\n', '\r' }, StringSplitOptions.RemoveEmptyEntries);
        int n = int.Parse(lines[0].Trim());
        List<(int, int)> p = new List<(int, int)>(n);

        for (int i = 1; i <= n; i++)
        {
            var coords = lines[i].Trim().Split(new[] { ' ', '\t' }, StringSplitOptions.RemoveEmptyEntries)
                .Select(int.Parse).ToArray();
            p.Add((coords[0], coords[1]));
        }

        int ans = 0;
        int cnt = 0;
        int[,] r = new int[n, n];
        int[] q = new int[n];

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                int dx = Math.Abs(p[i].Item1 - p[j].Item1);
                int dy = Math.Abs(p[i].Item2 - p[j].Item2);
                if (Gcd(dx, dy) % 4 == 0)
                {
                    cnt++;
                    r[i, j] = 1;
                    q[i]++;
                    ans += n - 2;
                }
            }
        }

        for (int i = 0; i < n; i++)
        {
            for (int j = 1; j < n; j++)
            {
                if (r[i, j] == 1)
                {
                    ans -= q[j] * 2;
                }
            }
        }

        Console.WriteLine(ans);
    }

    static int Gcd(int a, int b)
    {
        while (b != 0)
        {
            int t = b;
            b = a % b;
            a = t;
        }
        return a;
    }
}

