std::vector<int> next_larger_element(const std::vector<int>& arr, size_t n, bool f) {
    std::stack<size_t> s;
    std::vector<int> ans(n, -1);
    for (size_t i = 0; i < n; ++i) {
        while (!s.empty() && arr[s.top()] < arr[i]) {
            s.pop();
        }
        if (!s.empty()) {
            ans[i] = static_cast<int>(s.top());
        }
        s.push(i);
    }
    if (f) {
        for (size_t i = 0; i < n; ++i) {
            if (ans[i] != -1) {
                ans[i] = static_cast<int>(n - 1) - ans[i];
            }
        }
    }
    return ans;
}

int dfs(size_t i, const std::vector<std::vector<size_t>>& adj, size_t p, int ans) {
    bool f = true;
    int a1 = 0;
    for (size_t j : adj[i]) {
        if (j != p) {
            a1 += dfs(j, adj, i, ans + 1);
            f = false;
        }
    }
    if (f) {
        a1 += ans * (ans - 1) / 2;
    }
    return a1;
}

