class Dsu {
public:
    std::vector<size_t> parent;

    Dsu(size_t n) : parent(n + 1) {
        for (size_t i = 1; i <= n; ++i) {
            parent[i] = i;
        }
    }

    size_t find_parent(size_t node) {
        if (node == parent[node]) {
            return node;
        }
        parent[node] = find_parent(parent[node]);
        return parent[node];
    }

    int union_sets(size_t u, size_t v) {
        size_t u_parent = find_parent(u);
        size_t v_parent = find_parent(v);

        if (u_parent != v_parent) {
            parent[v_parent] = u_parent;
            return 0;
        } else {
            return -1;
        }
    }

    void check_component(size_t u, size_t v) {
        if (find_parent(u) != find_parent(v)) {
            std::cout << "Both belongs to different components" << std::endl;
        } else {
            std::cout << "same component" << std::endl;
        }
    }
};

