const int MOD = 998244353;

int bin_pow(int a, int b) {
    long long res = 1;
    while (b > 0) {
        a %= MOD;
        if (b & 1) {
            res = (res * a) % MOD;
        }
        b >>= 1;
        a = (a * a) % MOD;
    }
    return static_cast<int>(res);
}

int mod_inverse(int a) {
    return bin_pow(a, MOD - 2);
}

int mul(int a, int b) {
    return (static_cast<long long>(a) * b) % MOD;
}

int n_cr(int n, int r, const std::vector<int>& fact, const std::vector<int>& inv_fact) {
    if (r > n) return 0;
    int res = mul(fact[n], inv_fact[r]);
    res = mul(res, inv_fact[n - r]);
    return res;
}

