    size_t pos;
    size_t end;

    FastIO() : buffer(BUFSIZE, 0), pos(0), end(0) {}

    void read() {
        while (true) {
            auto n = std::cin.read(buffer.data() + end, BUFSIZE - end).gcount();
            if (n == 0) break;
            end += n;
        }
    }

    bool readline(std::string& result) {
        while (!is_empty() || read()) {
            while (pos < end && buffer[pos] != '\n') {
                result.push_back(buffer[pos]);
                ++pos;
            }
            if (pos < end) {
                // Skip the newline character
                ++pos;
                return true;
            }
        }
        return false;
    }

    bool is_empty() const {
        return pos == end;
    }
};

