import Foundation

let MOD: Int64 = 998244353

func binPow(_ a: Int64, _ b: Int64) -> Int64 {
    var res = Int64(1)
    var a = a % MOD
    var b = b
    while b > 0 {
        if b & 1 == 1 {
            res = (res * a) % MOD
        }
        b >>= 1
        a = (a * a) % MOD
    }
    return res
}

func modInverse(_ a: Int64) -> Int64 {
    return binPow(a, MOD - 2)
}

func mul(_ a: Int64, _ b: Int64) -> Int64 {
    return (a * b) % MOD
}

func nCr(_ n: Int, _ r: Int, _ fact: [Int64], _ invFact: [Int64]) -> Int64 {
    var res = mul(fact[n], invFact[r])
    res = mul(res, invFact[n - r])
    return res
}

func main() {
    let stdin = FileHandle.standardInput
    let data = stdin.readDataToEndOfFile()
    guard let input = String(data: data, encoding: .utf8) else { fatalError("Failed to read input") }

    let lines = input.split(separator: "\n")
    let n = Int(lines[0])!

    var ls = [String]()
    var black = 0
    var white = 0
    var full = false

    for i in 1...n {
        let line = String(lines[i])
        ls.append(line)
        if line.first == "W" {
            white += 1
        }
        if line.first == "B" {
            black += 1
        }
        if line.dropFirst().first == "W" {
            white += 1
        }
        if line.dropFirst().first == "B" {
            black += 1
        }
        if line.first != "?" && line.first == line.dropFirst().first {
            full = true
        }
    }

    if black > n || white > n {
        print("0")
        return
    }

    var fact = [Int64](repeating: 0, count: 2 * n + 1)
    var invFact = [Int64](repeating: 0, count: 2 * n + 1)
    fact[0] = 1
    invFact[0] = 1

    for i in 1...2 * n {
        fact[i] = mul(fact[i - 1], Int64(i))
        invFact[i] = modInverse(fact[i])
    }

    let empty = 2 * n - black - white
    var ans = nCr(empty, n - black, fact, invFact)

    if full {
        print(ans)
        return
    }

    var invalid = Int64(1)
    var wb = true
    var bw = true

    for line in ls {
        if line.first == "?" && line.dropFirst().first == "?" {
            invalid = mul(invalid, 2)
        }
        if line.first == "B" || line.dropFirst().first == "W" {
            wb = false
        }
        if line.first == "W" || line.dropFirst().first == "B" {
            bw = false
        }
    }

    if wb {
        invalid -= 1
    }
    if bw {
        invalid -= 1
    }

    ans -= invalid
    print(ans)
}

