let BUFSIZE: Int = 8192

class FastIO {
    var buffer: [UInt8]
    var pos: Int
    var end: Int

    init() {
        self.buffer = Array(repeating: 0, count: BUFSIZE)
        self.pos = 0
        self.end = 0
    }

    func read() throws {
        while true {
            let n = try FileHandle.standardInput.read(into: &buffer[end..<BUFSIZE])
            if n == 0 {
                break
            }
            end += n
        }
    }

    func readline() throws -> String {
        var result = ""
        while !isEmpty() || (try? read()) != nil {
            while pos < end && buffer[pos] != UInt8(ascii: "\n") {
                if let char = UnicodeScalar(buffer[pos]) {
                    result.append(Character(char))
                }
                pos += 1
            }
            if pos < end {
                // Skip the newline character
                pos += 1
                break
            }
        }
        return result
    }

    func isEmpty() -> Bool {
        return pos == end
    }
}

