function nextLargerElement(arr: number[], n: number, f: boolean): number[] {
    const s: number[] = [];
    const ans: number[] = new Array(n).fill(-1);
    for (let i = 0; i < n; i++) {
        while (s.length > 0 && arr[s[s.length - 1]] < arr[i]) {
            s.pop();
        }
        if (s.length > 0) {
            ans[i] = s[s.length - 1];
        }
        s.push(i);
    }
    if (f) {
        for (let i = 0; i < n; i++) {
            if (ans[i] !== -1) {
                ans[i] = n - 1 - ans[i];
            }
        }
    }
    return ans;
}

function dfs(i: number, adj: number[][], p: number, ans: number): number {
    let f = true;
    let a1 = 0;
    for (const j of adj[i]) {
        if (j !== p) {
            a1 += dfs(j, adj, i, ans + 1);
            f = false;
        }
    }
    if (f) {
        a1 += ans * (ans - 1) / 2;
    }
    return a1;
}

