	ans := make([]int, n)
	for i := 0; i < n; i++ {
		for len(s) > 0 && arr[s[len(s)-1]] < arr[i] {
			s = s[:len(s)-1]
		}
		if len(s) > 0 {
			ans[i] = s[len(s)-1]
		}
		s = append(s, i)
	}
	if f {
		for i := 0; i < n; i++ {
