	f := true
	a1 := 0
	for _, j := range adj[i] {
		if j != p {
			a1 += dfs(j, adj, i, ans+1)
			f = false
		}
	}
	if f {
		a1 += ans * (ans - 1) / 2
	}
	return a1
}

