const mod = 998244353

func egcd(a, b int) (int, int, int) {
	if a == 0 {
		return b, 0, 1
	}
	g, y, x := egcd(b%a, a)
	return g, x - (b/a)*y, y
}

func modinv(a, m int) int {
	g, x, _ := egcd(a, m)
	if g != 1 {
		panic("modular inverse does not exist")
	}
	return (x%m + m) % m
}

func choose(n, k, p int) int {
	if k == 0 || k == n {
		return 1
	}
	x := n
	for y := n - 1; y > n-k; y-- {
		x = (x * y) % p
	}
	d := 1
	for i := 2; i <= k; i++ {
		d = (d * i) % p
	}
	return (x * modinv(d, p)) % p
}

func solve() {
	scanner := bufio.NewScanner(os.Stdin)
	if !scanner.Scan() {
		return
	}
	nStr := scanner.Text()
	n, err := strconv.Atoi(nStr)
	if err != nil {
		return
	}

	wb_poss := true
	bw_poss := true
	w := 0
	b := 0
	q := 0
	free := 0
	any_bad_poss := true

	for i := 0; i < n; i++ {
		if !scanner.Scan() {
			return
		}
		s := strings.TrimSpace(scanner.Text())
		if len(s) == 2 && s[0] == '?' && s[1] == '?' {
			free++
		} else if len(s) == 2 && s[0] == s[1] {
			any_bad_poss = false
		}

		if s[0] == 'B' {
			b++
			wb_poss = false
		} else if s[0] == 'W' {
			w++
			bw_poss = false
		} else if s[0] == '?' {
			q++
		}

		if s[len(s)-1] == 'B' {
			b++
			bw_poss = false
		} else if s[len(s)-1] == 'W' {
			w++
			wb_poss = false
		} else if s[len(s)-1] == '?' {
			q++
		}
	}

	w_needed := n - b
	if w_needed > q || w_needed < 0 {
		fmt.Println(0)
		return
	}

	var num_bad_poss int
	if any_bad_poss {
		num_bad_poss = int(new(big.Int).Exp(big.NewInt(2), big.NewInt(int64(free)), nil).Int64()) % mod
		if bw_poss {
			num_bad_poss--
		}
		if wb_poss {
			num_bad_poss--
		}
	} else {
		num_bad_poss = 0
	}

	fmt.Println((choose(q, w_needed, mod)-num_bad_poss+mod)%mod)
}

