			if gcd(dx, dy)%4 == 0 {
				cnt++
				r[i][j] = 1
				q[i]++
				ans += n - 2
			}
		}
	}

	for i := 0; i < n; i++ {
		for j := 1; j < n; j++ {
			if r[i][j] == 1 {
				ans -= q[j] * 2
			}
		}
	}

	fmt.Println(ans)
}

