import java.util.*;

public class Main {
    public static int[] nextLargerElement(int[] arr, int n, boolean f) {
        Stack<Integer> s = new Stack<>();
        int[] ans = new int[n];
        Arrays.fill(ans, -1);

        for (int i = 0; i < n; i++) {
            while (!s.isEmpty() && arr[s.peek()] < arr[i]) {
                s.pop();
            }
            if (!s.isEmpty()) {
                ans[i] = s.peek();
            }
            s.push(i);
        }

        if (f) {
            for (int i = 0; i < n; i++) {
                if (ans[i] != -1) {
                    ans[i] = n - 1 - ans[i];
                }
            }
        }

        return ans;
    }

    public static int dfs(int i, List<List<Integer>> adj, int p, int ans) {
        boolean f = true;
        int a1 = 0;

        for (int j : adj.get(i)) {
            if (j != p) {
                a1 += dfs(j, adj, i, ans + 1);
                f = false;
            }
        }

        if (f) {
            a1 += ans * (ans - 1) / 2;
        }

        return a1;
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        int t = scanner.nextInt();

        for (int _t = 0; _t < t; _t++) {
            String[] input = scanner.nextLine().split(" ");
            List<Integer> numbers = Arrays.stream(input).map(Integer::parseInt).toList();

            if (numbers.size() < 2) continue;

            int n = numbers.get(0);
