import java.util.*;

public class Main {
    static class Dsu {
        int[] parent;

        public Dsu(int n) {
            this.parent = new int[n + 1];
        }

        public void makeSet() {
            for (int i = 1; i <= parent.length - 1; i++) {
                parent[i] = i;
            }
        }

        public int findParent(int node) {
            if (node == parent[node]) {
                return node;
            }

            parent[node] = findParent(parent[node]);
            return parent[node];
        }

        public int union(int u, int v) {
            int uParent = findParent(u);
            int vParent = findParent(v);

            if (uParent != vParent) {
                parent[vParent] = uParent;
                return 0;
            } else {
                return -1;
            }
        }

        public void checkComponent(int u, int v) {
            if (findParent(u) != findParent(v)) {
                System.out.println("Both belongs to different components");
            } else {
                System.out.println("same component");
            }
        }
    }

    static List<Integer> mp() {
        return Arrays.stream(new Scanner(System.in).nextLine().split(" "))
                     .map(Integer::parseInt)
                     .collect(Collectors.toList());
    }

    static int it() {
        return Integer.parseInt(new Scanner(System.in).nextLine());
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        String[] input = scanner.nextLine().split(" ");
        int n = Integer.parseInt(input[0]);
        int m1 = Integer.parseInt(input[1]);
        int m2 = Integer.parseInt(input[2]);

        Dsu d1 = new Dsu(n);
        Dsu d2 = new Dsu(n);
        d1.makeSet();
        d2.makeSet();

        int flag = 0;

        for (int i = 0; i < m1; i++) {
            List<Integer> uv = mp();
            int u = uv.get(0);
            int v = uv.get(1);
            if (d1.union(u, v) == -1) {
                flag = 1;
            }
        }

        for (int i = 0; i < m2; i++) {
            List<Integer> uv = mp();
            int u = uv.get(0);
            int v = uv.get(1);
            if (d2.union(u, v) == -1) {
                flag = 1;
            }
        }

        if (flag != 0) {
            System.out.println(0);
            System.exit(0);
        }

        List<int[]> v = new ArrayList<>();

        for (int i = 1; i <= n - 1; i++) {
            for (int j = i + 1; j <= n; j++) {
                int y = d1.findParent(j);
                int y1 = d1.findParent(y);
                int x = d2.findParent(j);
                int x1 = d2.findParent(x);

                if (d1.union(i, j) == -1) {
                    d1.parent[y] = y1;
                } else if (d2.union(i, j) == -1) {
                    d2.parent[x] = x1;
                    d1.parent[y] = y1;
                } else {
                    d1.union(i, j);
                    d2.union(i, j);
                    v.add(new int[]{i, j});
                }
            }
        }

        System.out.println(v.size());
        for (int[] pair : v) {
            System.out.println(pair[0] + " " + pair[1]);
        }
    }
}

