import java.util.Scanner;

public class Main {

    private static final int MOD = 998244353;

    public static void main(String[] args) {
        solve();
    }

    private static int egcd(int a, int b) {
        if (a == 0) {
            return b;
        } else {
            int[] result = extendedGCD(a, b);
            return result[0];
        }
    }

    private static int modinv(int a, int m) {
        int[] result = extendedGCD(a, m);
        if (result[0] != 1) {
            throw new RuntimeException("modular inverse does not exist");
        } else {
            return ((result[1] % m + m) % m);
        }
    }

    private static int choose(int n, int k, int p) {
        if (k == 0 || k == n) {
            return 1;
        }
        int x = n;
        for (int y = n - 1; y >= n - k + 1; y--) {
            x = (x * y) % p;
        }
        int d = 1;
        for (int i = 2; i <= k; i++) {
            d = (d * i) % p;
        }
        return (x * modinv(d, p)) % p;
    }

    private static void solve() {
        Scanner scanner = new Scanner(System.in);
        if (!scanner.hasNext()) {
            return;
        }
        int n = scanner.nextInt();
        boolean wb_poss = true;
        boolean bw_poss = true;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        boolean any_bad_poss = true;

        for (int i = 0; i < n; i++) {
            if (!scanner.hasNext()) {
                return;
            }
            String s = scanner.next().trim();
            if (s.charAt(0) == 'B') {
                b++;
                wb_poss = false;
            } else if (s.charAt(0) == 'W') {
                w++;
                bw_poss = false;
            } else if (s.charAt(0) == '?') {
                q++;
            }

            if (s.charAt(s.length() - 1) == 'B') {
                b++;
                bw_poss = false;
            } else if (s.charAt(s.length() - 1) == 'W') {
                w++;
                bw_poss = false;
            } else if (s.charAt(s.length() - 1) == '?') {
                q++;
            }

            if (s.equals("??")) {
                free++;
            } else if (s.charAt(0) == s.charAt(s.length() - 1)) {
                any_bad_poss = false;
            }
        }

        int w_needed = n - b;
        if (w_needed > q || w_needed < 0) {
            System.out.println(0);
            return;
        }

        int num_bad_poss;
        if (any_bad_poss) {
            num_bad_poss = (int) Math.pow(2, free) % MOD;
            num_bad_poss -= (bw_poss ? 1 : 0) + (wb_poss ? 1 : 0);
        } else {
            num_bad_poss = 0;
        }

        System.out.println((choose(q, w_needed, MOD) - num_bad_poss + MOD) % MOD);
    }

    private static int[] extendedGCD(int a, int b) {
        if (a == 0) {
            return new int[]{b, 0, 1};
        }
        int[] result = extendedGCD(b % a, a);
        int g = result[0];
        int x = result[1];
        int y = result[2];
        return new int[]{g, y - (b / a) * x, x};
    }
}

