using System;
using System.Collections.Generic;

class Program
{
    static int[] NextLargerElement(int[] arr, int n, bool f)
    {
        Stack<int> s = new Stack<int>();
        int[] ans = new int[n];
        for (int i = 0; i < n; i++)
        {
            while (s.Count > 0 && arr[s.Peek()] < arr[i])
            {
                s.Pop();
            }
            if (s.Count > 0)
            {
                ans[i] = s.Peek();
            }
            s.Push(i);
        }
        if (f)
        {
            for (int i = 0; i < n; i++)
            {
                if (ans[i] != -1)
                {
                    ans[i] = n - 1 - ans[i];
                }
            }
        }
        return ans;
    }

    static int Dfs(int i, List<List<int>> adj, int p, int ans)
    {
        bool f = true;
        int a1 = 0;
        foreach (int j in adj[i])
        {
            if (j != p)
            {
                a1 += Dfs(j, adj, i, ans + 1);
                f = false;
            }
        }
        if (f)
        {
            a1 += ans * (ans - 1) / 2;
        }
        return a1;
    }

    static void Main()
    {
        string input = Console.ReadLine();
        if (int.TryParse(input, out int t))
        {
            for (int _ = 0; _ < t; _++)
            {
                input = Console.ReadLine();
                var parts = input.Split(' ');
                if (parts.Length >= 2 && int.TryParse(parts[0], out int n) && int.TryParse(parts[^1], out int s))
                {
                    Console.WriteLine(s / ((n + 2) / 2));
                }
            }
        }
    }
}

