                        {
                            numbers.Add(parsedNum);
                        }
                    }

                    int ans = int.MaxValue;

                    for (int j = 0; j < 3; j++)
                    {
                        for (int k = 0; k < 3; k++)
                        {
                            int[][] mod3 = new int[10][];
                            for (int l = 0; l < 10; l++)
                            {
                                mod3[l] = new int[] { 0, int.MaxValue };
                            }
                            mod3[0][0] = 1;
                            mod3[0][1] = 0;

                            for (int l = 0; l <= j; l++)
                            {
                                for (int m = 0; m <= k; m++)
                                {
                                    int index = l + m * 2;
                                    if (index < 10)
                                    {
                                        mod3[index][0] = 1;
                                        mod3[index][1] = Math.Min(l + m, mod3[index][1]);
                                    }
                                }
                            }

                            int mx = 0;

                            foreach (var num in numbers)
                            {
                                int mod = num % 3;
                                int mn = int.MaxValue;

                                for (int i = mod; i <= num; i += 3)
                                {
                                    if (i < 10 && mod3[i][0] == 1)
                                    {
                                        mn = Math.Min((num - i) / 3, mn);
                                    }
                                }

                                mx = Math.Max(mx, mn);
                            }

                            if (mx != int.MaxValue)
                            {
                                ans = Math.Min(ans, mx + j + k);
                            }
                        }
                    }

