using System;

class Program
{
    const int Mod = 998244353;

    static (int, int, int) Egcd(int a, int b)
    {
        if (a == 0)
        {
            return (b, 0, 1);
        }
        else
        {
            var (g, y, x) = Egcd(b % a, a);
            return (g, x - (b / a) * y, y);
        }
    }

    static int Modinv(int a, int m)
    {
        var (g, x, _) = Egcd(a, m);
        if (g != 1)
        {
            throw new InvalidOperationException("modular inverse does not exist");
        }
        else
        {
            return (x % m + m) % m;
        }
    }

    static int Choose(int n, int k, int p)
    {
        if (k == 0 || k == n)
        {
            return 1;
        }
        long x = n;
        for (int y = n - 1; y >= n - k + 1; y--)
        {
            x = (x * y) % p;
        }
        int d = 1;
        for (int i = 2; i <= k; i++)
        {
            d = (d * i) % p;
        }
        return (int)((x * Modinv(d, p)) % p);
    }

    static void Solve()
    {
        if (!int.TryParse(Console.ReadLine(), out int n))
        {
            return;
        }
        bool wb_poss = true;
        bool bw_poss = true;
        int w = 0;
        int b = 0;
        int q = 0;
        int free = 0;
        bool any_bad_poss = true;

        for (int i = 0; i < n; i++)
        {
            string s = Console.ReadLine()?.Trim();
            if (s == null)
            {
                return;
            }
            if (s[0] == 'B')
            {
                b++;
                wb_poss = false;
            }
            else if (s[0] == 'W')
            {
                w++;
                bw_poss = false;
            }
            else if (s[0] == '?')
            {
                q++;
            }

            if (s[s.Length - 1] == 'B')
            {
                b++;
                bw_poss = false;
            }
            else if (s[s.Length - 1] == 'W')
            {
                w++;
                wb_poss = false;
            }
            else if (s[s.Length - 1] == '?')
            {
                q++;
            }

            if (s == "??")
            {
                free++;
            }
            else if (s[0] == s[s.Length - 1])
            {
                any_bad_poss = false;
            }
        }

        int w_needed = n - b;
        if (w_needed > q || w_needed < 0)
        {
            Console.WriteLine(0);
            return;
        }

        int num_bad_poss;
        if (any_bad_poss)
        {
            num_bad_poss = PowerMod(2, free, Mod);
            num_bad_poss -= (bw_poss ? 1 : 0) + (wb_poss ? 1 : 0);
            if (num_bad_poss < 0)
            {
                num_bad_poss += Mod;
            }
        }
        else
        {
            num_bad_poss = 0;
        }

        Console.WriteLine((Choose(q, w_needed, Mod) - num_bad_poss + Mod) % Mod);
    }

    static int PowerMod(int baseNum, int exponent, int modulus)
    {
        if (modulus == 1) return 0;
        long result = 1;
        long baseN = baseNum % modulus;
        while (exponent > 0)
        {
            if ((exponent & 1) == 1)
                result = (result * baseN) % modulus;
            exponent >>= 1;
            baseN = (baseN * baseN) % modulus;
        }
        return (int)result;
    }

    static void Main(string[] args)
    {
        Solve();
    }
}

using System;
using System.Collections.Generic;

class Program
{
    static void Main()
    {
        int n = int.Parse(Console.ReadLine());
        List<List<int>> p = new List<List<int>>();
        for (int i = 0; i < n; i++)
        {
            var line = Console.ReadLine().Split(' ');
            List<int> row = new List<int>();
            foreach (var item in line)
            {
                row.Add(int.Parse(item));
            }
            p.Add(row);
        }

        int ans = 0;
        int cnt = 0;
        int[,] r = new int[n, n];
        int[] q = new int[n];

        for (int i = 0; i < n; i++)
        {
            for (int j = i + 1; j < n; j++)
            {
                int dx = Math.Abs(p[i][0] - p[j][0]);
                int dy = Math.Abs(p[i][1] - p[j][1]);
                if (Gcd(dx, dy) % 4 == 0)
                {
                    cnt++;
                    r[i, j] = 1;
                    q[i]++;
                    ans += n - 2;
                }
            }
        }

        for (int i = 0; i < n; i++)
        {
            for (int j = 1; j < n; j++)
            {
                if (r[i, j] == 1)
                {
                    ans -= q[j] * 2;
                }
            }
        }

        Console.WriteLine(ans);
    }

    static int Gcd(int a, int b)
    {
        return b == 0 ? a : Gcd(b, a % b);
    }
}

