    let input: Vec<i32> = lines.next().unwrap().expect("Failed to read line")
        .split_whitespace()
        .map(|s| s.parse().expect("Please type a number!"))
        .collect();
    let n = input[0] as usize;
    let m = input[1] as usize;

    let mut s: Vec<String> = vec![String::new(); N];
    for i in 1..=n {
        s[i] = lines.next().unwrap().expect("Failed to read line");
    }

    let mut d: Vec<i32> = vec![0; N];
    for i in 1..=m {
        for j in (2..=n).step_by(1) {
            if s[j].len() > i - 1 && s[j - 1].len() > i &&
                s[j].as_bytes()[i - 1] == b'X' &&
                s[j - 1].as_bytes()[i] == b'X' {
                d[i] = 1;
                break;
            }
        }
    }

    for i in 1..=m {
        d[i] += d[i - 1];
    }

    let q: usize = lines.next().unwrap().expect("Failed to read line")
        .parse().expect("Please type a number!");

    for _ in 0..q {
        let query: Vec<i32> = lines.next().unwrap().expect("Failed to read line")
            .split_whitespace()
            .map(|s| s.parse().expect("Please type a number!"))
            .collect();
        let l = query[0] as usize;
        let r = query[1] as usize;

        if d[r - 1] - d[l - 1] != 0 {
            println!("NO");
        } else {
            println!("YES");
        }
    }
}

