std::vector<int> nextLargerElement(const std::vector<int>& arr, int n, bool f) {
    std::stack<int> s;
    std::vector<int> ans(n, -1);
    for (int i = 0; i < n; ++i) {
        while (!s.empty() && arr[s.top()] < arr[i]) {
            s.pop();
        }
        if (!s.empty()) {
            ans[i] = s.top();
        }
        s.push(i);
    }
    if (f) {
        for (int i = 0; i < n; ++i) {
            if (ans[i] != -1) {
                ans[i] = n - 1 - ans[i];
            }
        }
    }
    return ans;
}

int dfs(int i, const std::vector<std::vector<int>>& adj, int p, int ans) {
    bool f = true;
    int a1 = 0;
    for (int j : adj[i]) {
        if (j != p) {
            a1 += dfs(j, adj, i, ans + 1);
            f = false;
        }
    }
    if (f) {
        a1 += ans * (ans - 1) / 2;
    }
    return a1;
}

