                std::istringstream iss(input);
                while (iss >> numStr) {
                    arInput.push_back(std::stoi(numStr));
                }

                int ans = std::numeric_limits<int>::max();

                for (int j = 0; j < 3; ++j) {
                    for (int k = 0; k < 3; ++k) {
                        std::vector<std::pair<int, int>> mod3(10, {0, std::numeric_limits<int>::max()});
                        mod3[0] = {1, 0};

                        for (int l = 0; l <= j; ++l) {
                            for (int m = 0; m <= k; ++m) {
                                int index = l + m * 2;
                                if (index < 10) {
                                    mod3[index] = {1, std::min(l + m, mod3[index].second)};
                                }
                            }
                        }

                        int mx = 0;

                        for (int num : arInput) {
                            int mod = num % 3;
                            int mn = std::numeric_limits<int>::max();

                            for (int i = mod; i <= num; i += 3) {
                                if (i < 10 && mod3[i].first == 1) {
                                    mn = std::min((num - i) / 3, mn);
                                }
                            }

                            mx = std::max(mx, mn);
                        }

                        if (mx != std::numeric_limits<int>::max()) {
                            ans = std::min(ans, mx + j + k);
                        }
                    }
                }

