class Dsu {
public:
    std::vector<int> parent;

    Dsu(int n) : parent(n + 1, 0) {}

    void makeSet() {
        for (int i = 1; i <= parent.size() - 1; ++i) {
            parent[i] = i;
        }
    }

    int findParent(int node) {
        if (node == parent[node]) {
            return node;
        }
        parent[node] = findParent(parent[node]);
        return parent[node];
    }

    int unionSet(int u, int v) {
        int uParent = findParent(u);
        int vParent = findParent(v);

        if (uParent != vParent) {
            parent[vParent] = uParent;
            return 0;
        } else {
            return -1;
        }
    }

    void checkComponent(int u, int v) {
        if (findParent(u) != findParent(v)) {
            std::cout << "Both belongs to different components" << std::endl;
        } else {
            std::cout << "same component" << std::endl;
        }
    }
};

