const int mod = 998244353;

std::tuple<int, int, int> egcd(int a, int b) {
    if (a == 0) {
        return std::make_tuple(b, 0, 1);
    } else {
        auto [g, y, x] = egcd(b % a, a);
        return std::make_tuple(g, x - (b / a) * y, y);
    }
}

int modinv(int a, int m) {
    auto [g, x, _] = egcd(a, m);
    if (g != 1) {
        throw std::runtime_error("modular inverse does not exist");
    } else {
        return (x % m + m) % m;
    }
}

int choose(int n, int k, int p) {
    if (k == 0 || k == n) {
        return 1;
    }
    long long x = n;
    for (int y = n - 1; y >= n - k + 1; --y) {
        x = (x * y) % p;
    }
    int d = 1;
    for (int i = 2; i <= k; ++i) {
        d = (d * i) % p;
    }
    return static_cast<int>((x * modinv(d, p)) % p);
}

void solve() {
    std::string nStr;
    if (!std::getline(std::cin, nStr)) return;
    int n = std::stoi(nStr);
    bool wb_poss = true;
    bool bw_poss = true;
    int w = 0;
    int b = 0;
    int q = 0;
    int free = 0;
    bool any_bad_poss = true;

    for (int i = 0; i < n; ++i) {
        std::string s;
        if (!std::getline(std::cin, s)) return;

        if (s.front() == 'B') {
            b += 1;
            wb_poss = false;
        } else if (s.front() == 'W') {
            w += 1;
            bw_poss = false;
        } else if (s.front() == '?') {
            q += 1;
        }

        if (s.back() == 'B') {
            b += 1;
            bw_poss = false;
        } else if (s.back() == 'W') {
            w += 1;
            wb_poss = false;
        } else if (s.back() == '?') {
            q += 1;
        }

        if (s == "??") {
            free += 1;
        } else if (s.front() == s.back()) {
            any_bad_poss = false;
        }
    }

    int w_needed = n - b;
    if (w_needed > q || w_needed < 0) {
        std::cout << 0 << std::endl;
        return;
    }

    int num_bad_poss;
    if (any_bad_poss) {
        long long num_free_combinations = 1;
        for (int i = 0; i < free; ++i) {
            num_free_combinations = (num_free_combinations * 2) % mod;
        }
        num_bad_poss = static_cast<int>(num_free_combinations);
        if (bw_poss) --num_bad_poss;
        if (wb_poss) --num_bad_poss;
    } else {
        num_bad_poss = 0;
    }

    std::cout << ((choose(q, w_needed, mod) - num_bad_poss + mod) % mod) << std::endl;
}

int main() {
    solve();
    return 0;
}

