            std::cout << -1 << std::endl;
        } else {
            std::cout << 2 << std::endl;
        }
    }
}

int main() {
    process();
    return 0;
}

#include <iostream>
#include <vector>
#include <string>

const int N = static_cast<int>(1e6) + 10;
std::vector<std::string> s(N);
std::vector<int> d(N);

int main() {
    int n, m;
    std::cin >> n >> m;

    for (int i = 1; i <= n; ++i) {
        std::cin >> s[i];
    }

    for (int i = 1; i <= m; ++i) {
        for (int j = 2; j <= n; ++j) {
            if (s[j].length() > i - 1 && s[j - 1].length() > i &&
                s[j][i - 1] == 'X' && s[j - 1][i] == 'X') {
                d[i] = 1;
                break;
            }
        }
    }

    for (int i = 1; i <= m; ++i) {
        d[i] += d[i - 1];
    }

    int q;
    std::cin >> q;
    while (q--) {
        int l, r;
        std::cin >> l >> r;

        if (d[r - 1] - d[l - 1] != 0) {
            std::cout << "NO\n";
        } else {
            std::cout << "YES\n";
        }
    }

    return 0;
}
